window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[59]={"id":"059","numero":59,"titre":"Sujet en situation de précarité","objectifs":[{"id":"59-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la précarité","contenu":"<p>La <span class=\"kw-def\">précarité</span> est définie comme l'<strong>absence d'une ou plusieurs des sécurités</strong> permettant aux personnes et familles d'assumer leurs obl<span class=\"kw-chiffre\">iga</span>tions professionnelles, familiales et sociales et de jouir de leurs droits fondamentaux.</p>\n\n      <div class=\"callout callout-info\">\n        <strong>Caractère essentiel.</strong> La précarité <em>ne caractérise pas une catégorie sociale particulière</em>, mais un <strong>ensemble de situations de non-sécurité et de fragilité économique, sociale et familiale</strong>. La notion de précarité est <span class=\"kw-chiffre\">plus large que celle de pauvreté</span> : un individu en précarité n'est pas forcément pauvre ni exclu.\n      </div>\n\n      <h4>Conditions indispensables à la santé (OMS)</h4>\n\n      <ul>\n        <li><strong>Se loger</strong>, se nourrir convenablement en quantité et qualité <em>(≠ se nourrir à volonté — piège QCM)</em></li>\n        <li>Accéder à <strong>l'éducation et à l'information</strong></li>\n        <li>Disposer d'un <strong>revenu suffisant, certain et stable</strong></li>\n        <li>Bénéficier d'un <strong>écosystème stable, protecteur</strong></li>\n        <li>Compter sur un <strong>apport durable de ressources</strong></li>\n        <li>Avoir droit à la <strong>justice sociale et un traitement équitable</strong></li>\n        <li>Sécurité <strong>physique et affective</strong></li>\n        <li>Capacités de <strong>communiquer, apprendre et s'exprimer</strong></li>\n      </ul>\n\n      <p><span class=\"kw-clinique\">Les</span> situations de précarité sont <span class=\"kw-alerte\">contraires aux droits fondamentaux des personnes</span>.</p>","frequence":0},{"id":"59-2","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir distinguer la précarité de la pauvreté, de la grande pauvreté et de l’exclusion, de la marginalisation, et de la vulnérabilité","contenu":"<p>Six entités <strong>cliniques et sociales distinctes</strong> à différencier — bien tomber dans <span class=\"kw-clinique\">les</span> QCM.</p>\n\n      <table >\n        <thead>\n          <tr><th>Entité</th><th>Définition</th><th>Marqueurs clés</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Précarité</span></td>\n            <td>Situation de <strong>fragilité / insécurité</strong> économique, sociale, familiale</td>\n            <td><span class=\"kw-def\">Prévalence</span> : <span class=\"kw-chiffre\">20-25 %</span> · FdR : chômage, faible revenu, conditions de travail à risque, nationalité étrangère</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Pauvreté</span></td>\n            <td>Niveau de vie <strong>inférieur au seuil de pauvreté</strong> (=<span class=\"kw-chiffre\"> 60 %</span> du niveau de vie médian en France)</td>\n            <td><span class=\"kw-def\">Prévalence</span> : <span class=\"kw-chiffre\">14 %</span> · Seuil = <strong>1 008 €/mois</strong> pour un célibataire</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Grande pauvreté (misère)</span></td>\n            <td>Défaillances socio-économiques + ruptures familiales + accidents de santé cumulés</td>\n            <td>Aboutit à une <strong>disqualification sociale</strong> et une <strong>marginalité subie</strong></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Exclusion</span></td>\n            <td>Impossibilité de bénéficier des <strong>mêmes droits sociaux</strong> qu'un autre individu, pendant une période plus ou moins longue</td>\n            <td><strong>Forme extrême de la précarité</strong> · Ex : patient non éligible au RSA</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Marginalisation</span></td>\n            <td>Concept proche de l'exclusion : <strong><span class=\"kw-alerte\">rupture</span> des liens sociaux</strong></td>\n            <td>Suite à une <strong>exclusion ou auto-exclusion</strong> de la société</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Vulnérabilité</span></td>\n            <td>Risque accru de subir un tort · <strong>état de fragilité matérielle ou morale</strong> conférant un risque d'exclusion sociale</td>\n            <td>État de <strong>transition</strong> entre intégration solide et désaffiliation</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Le triptyque de la désaffiliation sociale</h4>\n\n      <ol>\n        <li><strong>Intégration solide</strong> : stabilité professionnelle et sociabilité</li>\n        <li><strong>Vulnérabilité</strong> : fragilité matérielle ou morale, risque d'exclusion</li>\n        <li><strong>Désaffiliation</strong> : chômage, <span class=\"kw-def\">isolement</span> social, insécurité</li>\n      </ol>","frequence":2},{"id":"59-3","rang":"A","rubrique":"Définition","titre":"Connaître les principales situations à risque de précarité et le caractère dynamique de ces situations","contenu":"<h4>Principales situations à risque de précarité</h4>\n\n      <ul>\n        <li><strong>Chômage</strong> (durable, intermittent ou de longue durée)</li>\n        <li><strong>Faible niveau de ressources</strong> (revenu sous le seuil de pauvreté)</li>\n        <li><strong>Conditions de travail à risque</strong> : statuts et contrats précaires, temps partiel non choisi, contrats saisonniers</li>\n        <li><strong>Nationalité étrangère</strong>, en particulier en situation irrégulière</li>\n        <li><strong>Modes d'habitat insalubre</strong>, suroccupé ou temporaire</li>\n        <li><strong>Effets de <span class=\"kw-alerte\">rupture</span></strong> : deuils, <span class=\"kw-def\">isolement</span> affectif, intermittence du travail, séparation</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Caractère dynamique — concept fondamental.</strong> La précarité n'est <em>pas un état figé</em> : c'est un <span class=\"kw-def\">processus évolutif</span> qui peut s'aggraver (vers la grande pauvreté ou l'exclusion) ou régresser (avec un retour à l'emploi, l'ouverture de droits sociaux). La trajectoire est <strong>réversible dans <span class=\"kw-clinique\">les</span> deux sens</strong>.\n      </div>\n\n      <h4>Trois temps de la trajectoire sociale</h4>\n\n      <ol>\n        <li><strong>Intégration</strong> — stabilité professionnelle + réseau social</li>\n        <li><strong>Vulnérabilité</strong> — fragilité matérielle ou morale, risque d'exclusion (= zone de bascule)</li>\n        <li><strong>Désaffiliation</strong> — chômage, <span class=\"kw-def\">isolement</span>, perte des liens sociaux</li>\n      </ol>\n\n      <p>L'intervention <span class=\"kw-ttt\">médico-sociale précoce</span> au <span class=\"kw-def\">stade</span> de vulnérabilité est l'enjeu majeur pour éviter le glissement vers la désaffiliation.</p>","frequence":1},{"id":"59-4","rang":"A","rubrique":"Epidémiologie","titre":"Connaître l’épidémiologie de la précarité","contenu":"<h4>Chiffres clés à connaître (France)</h4>\n\n      <table >\n        <thead>\n          <tr><th>Indicateur</th><th>Valeur</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Prévalence</span> de la précarité</strong></td>\n            <td><span class=\"kw-chiffre\">20-25 %</span> de la population</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Prévalence</span> de la pauvreté</strong></td>\n            <td><span class=\"kw-chiffre\">14-15 %</span> (≈ 9 millions de personnes en 2019)</td>\n          </tr>\n          <tr>\n            <td><strong>Grande pauvreté</strong></td>\n            <td><span class=\"kw-chiffre\">2 millions</span> de personnes</td>\n          </tr>\n          <tr>\n            <td><strong>Seuil de pauvreté</strong></td>\n            <td><strong><span class=\"kw-chiffre\">60 %</span></strong> du niveau de vie médian = <span class=\"kw-chiffre\">1 008 €/mois</span> pour un célibataire</td>\n          </tr>\n          <tr>\n            <td><strong>RSA-socle (personne isolée)</strong></td>\n            <td><span class=\"kw-chiffre\">565 €/mois</span> · en dessous du seuil de pauvreté</td>\n          </tr>\n          <tr>\n            <td><strong>Bénéficiaires RSA</strong></td>\n            <td>+ <span class=\"kw-chiffre\">7,5 %</span> en 2020 (effet COVID)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 290 — Epidémiologie cancers</em></p>","frequence":0},{"id":"59-5","rang":"A","rubrique":"Prise en charge","titre":"Connaître la démarche pluriprofessionnelle (santé et sociale) nécessaire pour les personnes en situation de précarité","contenu":"<div class=\"callout callout-warn\">\n        <strong>Règle d'or EDN ⭐⭐⭐.</strong> Une <em>prise en charge médicale sans démarche sociale</em> est <span class=\"kw-alerte\">inutile</span> chez la personne précaire. La démarche est <strong>obl<span class=\"kw-chiffre\">iga</span>toirement pluriprofessionnelle</strong> — santé + social — pour que soient (ré-)ouverts <span class=\"kw-clinique\">les</span> droits du patient.\n      </div>\n\n      <h4>Axes de la démarche pluriprofessionnelle</h4>\n\n      <table >\n        <thead>\n          <tr><th>Axe</th><th>Actions clés</th><th>Acteurs</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Repérage</strong></td>\n            <td>\n              <ul>\n                <li>Identification des situations <strong>masquées</strong> (peur du jugement)</li>\n                <li><span class=\"kw-def\">Score</span> <strong>EPICES</strong> en centres d'examen de santé</li>\n                <li>Examen clinique ciblé (st<span class=\"kw-chiffre\">igm</span>ates physiques, troubles psy)</li>\n              </ul>\n            </td>\n            <td>Médecin traitant · PMI · centres de santé</td>\n          </tr>\n          <tr>\n            <td><strong>Ouverture des droits</strong></td>\n            <td>\n              <ul>\n                <li><strong>PUMa</strong> (assurance maladie de base)</li>\n                <li><strong>CSS</strong> (complémentaire)</li>\n                <li><strong>AME</strong> si situation irrégulière</li>\n                <li>Minima sociaux : RSA, AAH, ASS, APL…</li>\n              </ul>\n            </td>\n            <td>Assistante sociale · CPAM · CARSAT · CCAS</td>\n          </tr>\n          <tr>\n            <td><strong>Soins curatifs &amp; préventifs</strong></td>\n            <td>\n              <ul>\n                <li>Médecin traitant + parcours coordonné</li>\n                <li>Dépistages organisés (cancers, <span class=\"kw-clinique\">IST</span>, hépatites)</li>\n                <li><span class=\"kw-ci\">Vaccinations à jour</span></li>\n              </ul>\n            </td>\n            <td>Médecin généraliste · spécialistes · centres de <span class=\"kw-def\">dépistage</span></td>\n          </tr>\n          <tr>\n            <td><strong>Accès aux dispositifs spécifiques</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-ttt\">PASS</span>, <span class=\"kw-ttt\">LHSS</span>, <span class=\"kw-ttt\">EMPP</span></li>\n                <li><span class=\"kw-alerte\">SAMU</span> social (115)</li>\n                <li>Associations humanitaires (Croix-Rouge, Restos du cœur, ATD…)</li>\n              </ul>\n            </td>\n            <td>Hôpital public · associations · structures médico-sociales</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Plan-cadre national</h4>\n\n      <p><span class=\"kw-clinique\">Les</span> dispositifs s'inscrivent dans le <span class=\"kw-def\">Programme Régional pour l'Accès à la Prévention et aux Soins (PRAPS 2018-2022)</span> ⭐.</p>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 174 — Pathologie infectieuse du migrant · 290 — Epidémiologie cancers</em></p>","frequence":3},{"id":"59-6","rang":"A","rubrique":"Prise en charge","titre":"Connaître les modalités de repérage des personnes en situation de précarité","contenu":"<p>Le repérage repose sur un <span class=\"kw-clinique\">interrogatoire orienté</span>, un <strong>examen clinique attentif</strong> et un <strong>outil dédié</strong> (<span class=\"kw-def\">Score</span> EPICES).</p>\n\n      <h4>Interrogatoire orienté — questions clés</h4>\n\n      <ul>\n        <li>Bénéficie-t-il de l'<strong>Assurance maladie de base</strong> et d'une complémentaire ?</li>\n        <li>A-t-il des <strong>difficultés à payer</strong> <span class=\"kw-clinique\">les</span> consultations ou les traitements ?</li>\n        <li>Conditions de <strong>logement</strong> (insalubre, suroccupé, temporaire, sans domicile) ?</li>\n        <li>Statut professionnel (contrat précaire, temps partiel non choisi, chômage) ?</li>\n        <li><span class=\"kw-def\">Isolement</span> social, ruptures récentes (deuil, séparation, perte d'emploi) ?</li>\n      </ul>\n\n      <h4>Examen clinique — signes d'appel</h4>\n\n      <table >\n        <thead>\n          <tr><th>Catégorie</th><th>St<span class=\"kw-chiffre\">igm</span>ates à rechercher</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>St<span class=\"kw-chiffre\">igm</span>ates physiques</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Malnutrition</span> (<span class=\"kw-clinique\">perte de poids</span>, dénutrition)</li>\n                <li><span class=\"kw-clinique\">Lésions cutanées chroniques</span> (ulcères, <span class=\"kw-etio\">gale</span>, pédiculose)</li>\n                <li>Hygiène bucco-dentaire défaillante (foyers <span class=\"kw-etio\">infectieux</span>)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Troubles psychiques</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Désorientation spatio-temporelle</span></li>\n                <li><span class=\"kw-clinique\">Syndrome dépressif</span></li>\n                <li><span class=\"kw-def\">Isolement</span>, repli sur soi, méfiance vis-à-vis du système de soins</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong><span class=\"kw-def\">Score</span> EPICES ⭐</strong> — Évaluation de la Précarité et des Inégalités de santé dans <span class=\"kw-clinique\">les</span> Centres d'Examens de Santé. Outil <span class=\"kw-def\">multidimensionnel</span> à <strong>11 questions</strong>, utilisé dans les enquêtes en population générale.\n      </div>\n\n      <h4><span class=\"kw-clinique\">Les</span> 11 questions du <span class=\"kw-def\">Score</span> EPICES</h4>\n\n      <ol>\n        <li>Rencontrez-vous parfois un travailleur social ?</li>\n        <li>Bénéficiez-vous d'une assurance maladie complémentaire ?</li>\n        <li>Vivez-vous en couple ?</li>\n        <li>Êtes-vous propriétaire de votre logement ?</li>\n        <li>Y a-t-il des périodes dans le mois où vous rencontrez de réelles difficultés financières à faire face à vos besoins ?</li>\n        <li>Vous est-il arrivé de faire du sport au cours des 12 derniers mois ?</li>\n        <li>Êtes-vous allé au spectacle au cours des 12 derniers mois ?</li>\n        <li>Êtes-vous parti en vacances au cours des 12 derniers mois ?</li>\n        <li>Au cours des 6 derniers mois, avez-vous eu des contacts avec des membres de votre famille autres que vos parents ou vos enfants ?</li>\n        <li>En cas de difficultés, y a-t-il dans votre entourage des personnes sur qui vous puissiez compter pour vous héberger quelques jours en cas de besoin ?</li>\n        <li>En cas de difficultés, y a-t-il dans votre entourage des personnes sur qui vous puissiez compter pour vous apporter une aide matérielle ?</li>\n      </ol>\n\n      <p><strong>Seuil de précarité.</strong> Risque élevé si <span class=\"kw-chiffre\">≥ 4 réponses péjoratives sur 11</span> (≈ <span class=\"kw-def\">score</span> de 30/100). Plus le nombre de réponses négatives est élevé, plus la précarité sociale est importante.</p>","frequence":0,"liens":[{"href":"https://www.cetaf.fr/score-epices/","label":"CETAF — Score EPICES"}]},{"id":"59-7","rang":"A","rubrique":"Prise en charge","titre":"Connaître l’obligation de prise en charge des médecins et le secret professionnel vis-à-vis d’une personne en situation de précarité","contenu":"<div class=\"callout callout-warn\">\n        <strong>Obl<span class=\"kw-chiffre\">iga</span>tion déontologique absolue.</strong> <span class=\"kw-ci\">Refuser des soins à un patient au prétexte qu'il ne peut les payer est contraire au Code de la santé publique dans tous les cas</span>. Aucune exception — y compris pour <span class=\"kw-clinique\">les</span> bénéficiaires de la CSS ou de l'AME.\n      </div>\n\n      <h4>Obl<span class=\"kw-chiffre\">iga</span>tions des professionnels de santé</h4>\n\n      <ul>\n        <li><strong>Recevoir</strong> <span class=\"kw-clinique\">les</span> bénéficiaires de la CSS et de l'AME</li>\n        <li><strong>Respecter <span class=\"kw-clinique\">les</span> tarifs</strong> reconnus par l'Assurance maladie</li>\n        <li>Pratiquer la <strong>dispense d'avance de frais</strong> (tiers payant) pour ces assurés sociaux</li>\n        <li>Appliquer le <strong>parcours de soins coordonné</strong> (médecin traitant) aux bénéficiaires de la CSS</li>\n      </ul>\n\n      <h4>Refus de soins — formes à reconnaître</h4>\n\n      <table >\n        <thead>\n          <tr><th>Forme</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Refus direct</strong></td>\n            <td>Impossibilité de prendre rendez-vous, refus explicite de la consultation</td>\n          </tr>\n          <tr>\n            <td><strong>Refus indirect</strong></td>\n            <td>Retard à la rédaction de documents réglementaires, délais d'attente allongés, orientation systématique vers un autre praticien</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Secret professionnel</h4>\n\n      <div class=\"callout callout-info\">\n        <strong><span class=\"kw-alerte\">Hospitalisation</span> sans droits — sous secret médical.</strong> Quand une hospitalisation est indiquée pour un patient <span class=\"kw-chiffre\">sans droit ou sans statut</span> (étranger en situation irrégulière, sans-papiers), elle se fait <strong>sous secret médical</strong>. Le médecin ne signale jamais le statut administratif aux autorités.\n      </div>\n\n      <p>Le <span class=\"kw-def\">secret médical</span> protège également la prise en charge des migrants en situation irrégulière, des mineurs isolés et des victimes de violences — il prime sur toute considération administrative.</p>","frequence":0},{"id":"59-8","rang":"A","rubrique":"Définition","titre":"Connaître la définition des inégalités sociales en santé et les quatre mécanismes principaux qui y participent ; connaître le concept de gradient social de santé et son impact sur l’espérance de vie","contenu":"<h4>Définition</h4>\n\n      <p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">inégalités sociales en santé (ISS)</span> désignent les <strong>différences systématiques, évitables et injustes d'état de santé</strong> observées entre groupes sociaux, et reflètent la position sociale (catégorie socioprofessionnelle, revenu, niveau d'éducation, conditions de logement).</p>\n\n      <h4>Gradient social de santé</h4>\n\n      <div class=\"callout callout-info\">\n        <strong>Concept central.</strong> Le <span class=\"kw-def\">gradient social de santé</span> traduit le fait que l'état de santé se dégrade <em>progressivement</em> à mesure que l'on descend l'échelle sociale — il ne s'agit pas seulement d'une opposition « pauvres <span class=\"kw-bio\">vs</span> riches », mais d'un <strong>continuum</strong> qui concerne <strong>toute la société</strong>.\n      </div>\n\n      <h4>Impact sur l'espérance de vie</h4>\n\n      <table >\n        <thead>\n          <tr><th>Comparaison</th><th>Différentiel d'espérance de vie</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Cadres <span class=\"kw-bio\">vs</span> <strong>inactifs</strong></td>\n            <td><span class=\"kw-chiffre\">7 ans</span></td>\n          </tr>\n          <tr>\n            <td>Cadres <span class=\"kw-bio\">vs</span> <strong>ouvriers</strong></td>\n            <td><span class=\"kw-chiffre\">6 ans</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p><span class=\"kw-clinique\">Les</span> inégalités sont aussi retrouvées dans l'<strong>espérance de vie en bonne santé</strong> et la <strong>santé perçue</strong>.</p>\n\n      <h4><span class=\"kw-clinique\">Les</span> 4 mécanismes principaux des ISS</h4>\n\n      <ol>\n        <li><strong>Postes de travail dangereux ou pénibles</strong> — exposition à la pollution, rythmes irréguliers ou intenses, accidents du travail</li>\n        <li><strong>Styles de vie contraints par <span class=\"kw-clinique\">les</span> faibles ressources</strong> — malnutrition, pollutions internes/externes, transports plus longs et plus pénibles</li>\n        <li><strong>Cumul de <span class=\"kw-def\">facteurs de risque</span> individuels</strong> — plus forte consommation de produits psychotoxiques (<span class=\"kw-ttt\">tabac</span>, <span class=\"kw-ttt\">alcool</span>), <span class=\"kw-etio\">sédentarité</span></li>\n        <li><strong>Accès aux soins et à la prévention retardé</strong> — jugé non prioritaire ou différé par manque de ressources matérielles ou cognitives</li>\n      </ol>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 75 — Addiction <span class=\"kw-etio\">Tabac</span> · 76 — Addiction à l'<span class=\"kw-etio\">alcool</span></em></p>","frequence":0},{"id":"59-9","rang":"A","rubrique":"Epidémiologie, prévalence","titre":"Savoir que santé et précarité entretiennent des relations réciproques","contenu":"<div class=\"callout callout-info\">\n        <strong>Boucle de rétroaction.</strong> Santé et précarité s'<em>auto-entretiennent</em> : la précarité dégrade la santé, et la dégradation de la santé renforce la précarité. Cette <strong>réciprocité</strong> est le concept clé de l'item.\n      </div>\n\n      <h4><span class=\"kw-clinique\">Les</span> deux sens de la causalité</h4>\n\n      <table >\n        <thead>\n          <tr><th>Sens</th><th>Mécanismes</th><th>Conséquences</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Précarité → Santé dégradée</strong></td>\n            <td>\n              <ul>\n                <li>Conditions de vie défavorables (logement, alimentation)</li>\n                <li>Exposition professionnelle accrue</li>\n                <li>Stress chronique, <span class=\"kw-def\">isolement</span></li>\n                <li>Renoncement aux soins et à la prévention</li>\n              </ul>\n            </td>\n            <td>Surmorbidité (cardiovasculaire, métabolique, psy, infectieuse) et <span class=\"kw-alerte\">surmortalité</span></td>\n          </tr>\n          <tr>\n            <td><strong>Santé dégradée → Précarité</strong></td>\n            <td>\n              <ul>\n                <li>Perte d'emploi en cas de maladie chronique ou de handicap</li>\n                <li>Reste à charge non couvert, frais médicaux</li>\n                <li>Perte de revenus pendant arrêt de travail</li>\n                <li><span class=\"kw-def\">Isolement</span> social lié au handicap</li>\n              </ul>\n            </td>\n            <td>Bascule vers la <span class=\"kw-def\">grande pauvreté</span>, désaffiliation</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p>Cette boucle explique pourquoi la <strong>démarche pluriprofessionnelle</strong> (médico-sociale) est indispensable : agir uniquement sur l'axe médical ou uniquement sur l'axe social ne suffit pas à briser le cycle.</p>","frequence":1},{"id":"59-10","rang":"A","rubrique":"Prise en charge","titre":"Connaître les parcours de soins spécifiques des personnes en situation de précarité : PASS, LHSS, équipes mobiles psychiatrie-précarité (EMPP), structures associatives","contenu":"<p>Plusieurs dispositifs s'inscrivent dans le <span class=\"kw-def\">PRAPS 2018-2022</span> (Programme Régional pour l'Accès à la Prévention et aux Soins) ⭐.</p>\n\n      <h4>Dispositifs spécifiques médico-sociaux</h4>\n\n      <table >\n        <thead>\n          <tr><th>Dispositif</th><th>Public</th><th>Missions clés</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-ttt\">PASS</span><br><em>Permanences d'accès aux soins de santé</em></td>\n            <td>Personnes <strong>démunies, dépourvues d'Assurance maladie</strong></td>\n            <td>\n              <ul>\n                <li>Consultations externes, actes diagnostiques et thérapeutiques <strong>gratuits</strong></li>\n                <li>Accès au système hospitalier</li>\n                <li>Accompagnement aux démarches sociales (ouverture des droits)</li>\n                <li>Réponse aux demandes de <strong>contraception, IVG, accueil de jeunes enfants</strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\">LHSS</span><br><em>Lits halte soins santé</em></td>\n            <td><strong>Sans domicile fixe</strong> dont la pathologie ne nécessite pas une PEC hospitalière spécialisée mais est <strong>incompatible avec la vie à la rue</strong></td>\n            <td>\n              <ul>\n                <li>Ouverts <span class=\"kw-chiffre\">24h/24, tous les jours</span> · durée non limitée</li>\n                <li>Équipe pluridisciplinaire (principalement infirmiers)</li>\n                <li>Lit infirmier + évaluation médico-sociale</li>\n                <li>Orientation vers hébergement pérenne · soutien psychoéducatif</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\">EMPP</span><br><em>Équipes mobiles psychiatrie-précarité</em></td>\n            <td>Personnes en <strong>grande précarité</strong> psychique et sociale, empêchées d'accéder aux soins</td>\n            <td>\n              <ul>\n                <li><span class=\"kw-bio\">Complément</span> psychiatrique des PASS</li>\n                <li>Composées d'<strong>infirmiers, psychiatres, psychologues, assistants sociaux</strong></li>\n                <li>Interviennent <strong>à l'extérieur des établissements</strong> (« aller-vers »)</li>\n                <li>Repérage précoce, évaluation, orientation vers le dispositif de soins de droit commun</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">SAMU</span> social</strong></td>\n            <td>Personnes démunies en <strong>situation d'<span class=\"kw-alerte\">urgence</span></strong> (parisien à l'origine, étendu)</td>\n            <td>\n              <ul>\n                <li>Joint via le <span class=\"kw-chiffre\">115</span> (numéro d'appel d'<span class=\"kw-alerte\">urgence</span> sociale)</li>\n                <li>Orientation, hébergement d'<span class=\"kw-alerte\">urgence</span></li>\n                <li>Attente parfois longue ou sans aboutissement (besoins &gt; capacités)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Associations humanitaires</strong></td>\n            <td>Toutes situations</td>\n            <td>\n              <ul>\n                <li><strong>Généralistes</strong> : ATD Quart-Monde, Croix-Rouge, Secours catholique, Secours populaire</li>\n                <li><strong>Thématiques</strong> : Restos du cœur, Banque alimentaire, Planning familial</li>\n                <li><strong>Migrants</strong> : CIMADE, COMEDE, ISM (Interservices migrants)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Accès aux services sociaux en ville</h4>\n\n      <ul>\n        <li><strong>CCAS</strong> — Centres communaux d'action sociale (<span class=\"kw-clinique\">porte d'entrée</span> locale)</li>\n        <li><strong>Assistantes sociales</strong> des CPAM, des CARSAT (pour <span class=\"kw-clinique\">les</span> personnes âgées)</li>\n        <li><strong>Services sociaux du département</strong> · <strong>PMI</strong> (femmes enceintes + jeunes enfants)</li>\n        <li><strong>Travailleurs sociaux des associations</strong></li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 174 — Pathologie infectieuse du migrant</em></p>","frequence":1},{"id":"59-11","rang":"A","rubrique":"Prise en charge","titre":"Connaître la couverture médicale des personnes en situation de précarité","contenu":"<div class=\"callout callout-warn\">\n        <strong>Trois dispositifs à ne pas confondre ⭐⭐⭐.</strong> <span class=\"kw-def\">PUMa</span> (base universelle), <span class=\"kw-def\">CSS</span> (complémentaire pour revenus modestes), <span class=\"kw-def\">AME</span> (étrangers en situation irrégulière). <strong>L'AME est le SEUL dispositif</strong> applicable à un étranger en situation irrégulière ⭐ (piège tombé en annale).\n      </div>\n\n      <h4>PUMa — Protection universelle maladie</h4>\n\n      <ul>\n        <li>Remplace la <strong>CMU</strong> (assurance maladie de base)</li>\n        <li>Couvre toute personne résidant en France de <strong>façon stable et régulière</strong></li>\n        <li>Prend en charge la part de base des dépenses de santé</li>\n      </ul>\n\n      <h4>CSS — Complémentaire santé solidaire</h4>\n\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Historique</strong></td>\n            <td>Remplace la <strong>CMU-C</strong> et l'<strong>ACS</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Éligibilité</strong></td>\n            <td>\n              <ul>\n                <li>Personne vivant en France de façon <strong>stable et régulière</strong></li>\n                <li>Sous <strong>conditions de ressources</strong></li>\n                <li>≈ <span class=\"kw-chiffre\">9 000 €/an</span> pour une personne isolée (gratuite)</li>\n                <li>Jusqu'à <span class=\"kw-chiffre\">10 000 €/an</span> avec légère participation financière</li>\n                <li>Proposée à certains <strong>jeunes mineurs dès <span class=\"kw-chiffre\">16 ans</span></strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Couverture</strong></td>\n            <td>\n              <ul>\n                <li>Prise en charge <span class=\"kw-chiffre\">sans avance de frais</span> de la part complémentaire (ville + hôpital)</li>\n                <li>Forfaits dentaire, lunettes, prothèses auditives (peut bénéficier du <strong><span class=\"kw-chiffre\">100 %</span> Santé</strong>)</li>\n                <li><strong>Sans franchise médicale</strong> sur médicaments, actes paramédicaux, transports sanitaires</li>\n                <li><strong>Dispense de la participation forfaitaire</strong></li>\n                <li><strong>Exonération du forfait journalier</strong></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>AME — Aide médicale de l'État</h4>\n\n      <div class=\"callout callout-info\">\n        <strong>Seule aide applicable aux étrangers en situation irrégulière.</strong>\n      </div>\n\n      <table >\n        <thead>\n          <tr><th>Critère</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Éligibilité</strong></td>\n            <td>\n              <ul>\n                <li><strong>Étranger</strong> (nationalité étrangère)</li>\n                <li>En <strong>situation irrégulière</strong> (sans titre de séjour ni récépissé)</li>\n                <li>Résidant en France de manière <strong>stable et ininterrompue depuis &gt;<span class=\"kw-chiffre\"> 3 mois</span></strong></li>\n                <li><strong>Sans couverture maladie</strong></li>\n                <li>Ressources <strong>≤ plafond CSS</strong> (≈ 9-10 k€/an)</li>\n                <li><span class=\"kw-chiffre\">AME automatiquement accordée sans conditions pour les enfants mineurs</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Couverture</strong></td>\n            <td>\n              <ul>\n                <li>Prise en charge à <strong><span class=\"kw-chiffre\">100 %</span></strong> des soins médicaux et d'<span class=\"kw-alerte\">hospitalisation</span> (dans la limite des tarifs Sécu)</li>\n                <li><span class=\"kw-chiffre\">SANS AVANCE DE FRAIS</span> ⭐ (piège tombé en annale)</li>\n                <li>Exonération de la <strong>franchise médicale</strong>, de la <strong>participation forfaitaire</strong> et du <strong>forfait journalier</strong> ⭐</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>AME à titre humanitaire</strong></td>\n            <td>\n              <ul>\n                <li>Pour personnes étrangères <span class=\"kw-chiffre\">ne résidant pas en France</span>, à la demande d'un médecin</li>\n                <li>Accident ou maladie lors d'un passage en France (visa touristique/court séjour)</li>\n                <li>Soins impossibles dans le pays d'origine</li>\n                <li>Soins d'<span class=\"kw-alerte\">urgence</span> (<span class=\"kw-alerte\">pronostic vital engagé</span>)</li>\n                <li>Femmes enceintes et nouveau-nés</li>\n                <li>Maladies contagieuses</li>\n                <li>Décision : <strong>ministère chargé de l'Action sociale</strong></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>","frequence":3},{"id":"59-12","rang":"A","rubrique":"Prise en charge","titre":"Connaître les aides financières","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">minima sociaux</span> visent à limiter le cumul des risques vers l'état de grande pauvreté. Les droits sociaux français sont <strong>nombreux, parcellaires, non liés entre eux</strong> — il faut systématiquement <strong>demander l'ouverture des droits</strong>, et les <strong>renouveler à temps</strong>.</p>\n\n      <h4>Principaux dispositifs financiers</h4>\n\n      <table >\n        <thead>\n          <tr><th>Sigle</th><th>Intitulé</th><th>Conditions clés</th><th>Montant</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>RSA</strong></td>\n            <td>Revenu de solidarité active</td>\n            <td>\n              <ul>\n                <li><strong><span class=\"kw-chiffre\">≥ 25 ans</span></strong>, parents isolés <span class=\"kw-chiffre\">18-24 ans</span>, jeune &lt;<span class=\"kw-chiffre\"> 25 ans</span> ayant travaillé <span class=\"kw-chiffre\">≥ 2</span> des 3 dernières années</li>\n                <li>Résidant en France (étrangers avec <strong>titre de séjour</strong>, <em>pas</em> ceux en situation irrégulière)</li>\n                <li>Revenus inférieurs au plafond</li>\n                <li>Géré par <span class=\"kw-clinique\">les</span> <strong>conseils départementaux</strong></li>\n                <li>Contrepartie : parcours d'insertion sociale ou professionnelle</li>\n              </ul>\n            </td>\n            <td>RSA-socle isolé : <span class=\"kw-chiffre\">565 €/mois</span> (sous le seuil de pauvreté)</td>\n          </tr>\n          <tr>\n            <td><strong>AAH</strong></td>\n            <td>Allocation aux adultes handicapés</td>\n            <td>\n              <ul>\n                <li><strong><span class=\"kw-chiffre\">≥ 20 ans</span></strong></li>\n                <li>Résidant en France</li>\n                <li><strong>IP (incapacité permanente) <span class=\"kw-chiffre\">≥ 80 %</span></strong></li>\n                <li>Ressources sous plafond annuel</li>\n              </ul>\n            </td>\n            <td>Variable</td>\n          </tr>\n          <tr>\n            <td><strong>ASS</strong></td>\n            <td>Allocation spécifique de solidarité</td>\n            <td>Demandeurs d'emploi en fin de droits au chômage</td>\n            <td>Variable</td>\n          </tr>\n          <tr>\n            <td><strong>ASPA / <span class=\"kw-ttt\">APA</span></strong></td>\n            <td>Allocation spécifique aux personnes âgées</td>\n            <td>\n              <ul>\n                <li><strong><span class=\"kw-chiffre\">≥ 60 ans</span></strong></li>\n                <li>Résidant en France de manière stable et régulière</li>\n                <li><strong>AGGIR 1 à 4</strong> (perte d'autonomie)</li>\n              </ul>\n            </td>\n            <td>Variable selon GIR</td>\n          </tr>\n          <tr>\n            <td><strong>APL</strong></td>\n            <td>Aide personnalisée au logement</td>\n            <td>Sous conditions de ressources et de logement conventionné</td>\n            <td>Variable</td>\n          </tr>\n          <tr>\n            <td><strong>AEEH</strong></td>\n            <td>Allocation d'éducation de l'enfant handicapé</td>\n            <td>\n              <ul>\n                <li>Versée aux <strong>parents</strong></li>\n                <li>Enfant <strong><span class=\"kw-chiffre\">≤ 20 ans</span></strong></li>\n                <li>Selon nature et gravité du handicap</li>\n              </ul>\n            </td>\n            <td>Variable</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Piège des droits perdus.</strong> <span class=\"kw-clinique\">Les</span> minima sociaux peuvent être <span class=\"kw-alerte\">perdus s'ils ne sont pas renouvelés à temps</span>. Le rôle du médecin et du travailleur social est de <strong>vérifier régulièrement l'ouverture et le maintien des droits</strong>.\n      </div>","frequence":0},{"id":"59-13","rang":"A","rubrique":"Prise en charge","titre":"Connaître l’existence et les moyens de recours aux consultations gratuites","contenu":"<p>Plusieurs structures offrent des <span class=\"kw-def\">consultations gratuites</span> à toute personne, y compris en situation de précarité ou sans couverture.</p>\n\n      <h4>Structures de consultations gratuites</h4>\n\n      <table >\n        <thead>\n          <tr><th>Structure</th><th>Public</th><th>Offre</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Centres d'examen de santé</strong><br><em>de l'Assurance maladie</em></td>\n            <td>Tous, y compris bénéficiaires de l'AME</td>\n            <td>\n              <ul>\n                <li><strong>Bilans de santé gratuits</strong></li>\n                <li><span class=\"kw-def\">Score</span> EPICES</li>\n                <li>Travailleurs sociaux aidant à l'ouverture des droits</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>CDAG / CEGID</strong><br><em>Centres de <span class=\"kw-def\">dépistage</span> anonymes et gratuits</em></td>\n            <td>Tous</td>\n            <td>\n              <ul>\n                <li><span class=\"kw-def\">Dépistage</span> <strong><span class=\"kw-etio\">VIH</span></strong>, <strong>hépatites</strong>, <strong><span class=\"kw-clinique\">IST</span></strong></li>\n                <li><strong>Anonyme</strong> et <strong>gratuit</strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Dispensaires municipaux</strong> &amp; <strong>centres de santé</strong></td>\n            <td>Tous, populations fragiles surtout</td>\n            <td>Soins, prévention, <span class=\"kw-def\">dépistage</span> gratuits</td>\n          </tr>\n          <tr>\n            <td><strong>PASS</strong> hospitalières</td>\n            <td>Personnes démunies dépourvues d'AM</td>\n            <td>Consultations, actes diagnostiques et thérapeutiques gratuits</td>\n          </tr>\n          <tr>\n            <td><strong>PMI</strong><br><em>Protection maternelle et infantile</em></td>\n            <td>Femmes enceintes + enfants &lt;<span class=\"kw-chiffre\"> 6 ans</span></td>\n            <td>Consultations pédiatriques, vaccinations, contraception, <span class=\"kw-def\">suivi</span> de <span class=\"kw-ci\">grossesse</span> gratuits</td>\n          </tr>\n          <tr>\n            <td><strong>Planning familial</strong></td>\n            <td>Tous, mineurs sans consentement parental</td>\n            <td>Consultations contraception, IVG, <span class=\"kw-clinique\">IST</span> gratuites et anonymes</td>\n          </tr>\n          <tr>\n            <td><strong>Soins psychiatriques sectorisés</strong></td>\n            <td>Tous</td>\n            <td>CMP, CATTP — consultations gratuites en secteur</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Obstacle principal.</strong> Le <span class=\"kw-alerte\">non-recours aux soins</span> est le 1<sup>er</sup> obstacle à l'accès à ces dispositifs — méconnaissance, peur du jugement, complexité administrative, barrière linguistique.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span class=\"kw-ci\">Grossesse</span> normale · 162 — <span class=\"kw-clinique\">IST</span></em></p>","frequence":2},{"id":"59-14","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les 5 grands domaines de pathologies les plus fréquentes chez les personnes en situation de précarité","contenu":"<div class=\"callout callout-info\">\n        <strong>Mnémo des 5 domaines.</strong> <em>Cardio · Métabo · Addicto · Transmissible · Psy</em> — à savoir lister sans hésitation pour <span class=\"kw-clinique\">les</span> QCM.\n      </div>\n\n      <h4><span class=\"kw-clinique\">Les</span> <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>5</span> g</span>rands domaines de pathologies</h4>\n\n      <table >\n        <thead>\n          <tr><th>Domaine</th><th>Pathologies clés</th><th><span class=\"kw-def\">Surveillance</span></th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>1. Cardiovasculaire</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">HTA</span> ⭐</li>\n                <li>Coronaropathie, AOMI</li>\n              </ul>\n            </td>\n            <td>PA, <span class=\"kw-bio\">ECG</span>, <span class=\"kw-bio\">bilan lipidique</span></td>\n          </tr>\n          <tr>\n            <td><strong>2. Métabolique</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Diabète de la maturité</span> ⭐</li>\n                <li><span class=\"kw-clinique\">Obésité</span> ⭐</li>\n                <li><span class=\"kw-etio\">Dyslipidémie</span></li>\n              </ul>\n            </td>\n            <td><span class=\"kw-bio\">Glycémie</span>, IMC, tour de taille, <span class=\"kw-bio\">HbA1c</span></td>\n          </tr>\n          <tr>\n            <td><strong>3. Addictions</strong><br><em>Complications consommations abusives</em></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-ttt\">Alcool</span></li>\n                <li><span class=\"kw-ttt\">Tabac</span></li>\n                <li>Substances psychoactives</li>\n              </ul>\n            </td>\n            <td>AUDIT, Fagerström, <span class=\"kw-ttt\">sevrage</span> encadré</td>\n          </tr>\n          <tr>\n            <td><strong>4. Pathologies transmissibles</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Tuberculose</span></li>\n                <li><span class=\"kw-clinique\">VIH</span></li>\n                <li><span class=\"kw-clinique\">Hépatites B et C</span></li>\n                <li><span class=\"kw-clinique\">IST</span></li>\n              </ul>\n            </td>\n            <td><span class=\"kw-def\">Dépistage</span> ciblé (CDAG/CEGID), vaccinations, ITL</td>\n          </tr>\n          <tr>\n            <td><strong>5. Psychiatrique</strong></td>\n            <td>\n              <ul>\n                <li>Majoration des <strong>ATCD psychiatriques</strong></li>\n                <li><span class=\"kw-def\">Dépression</span>, troubles anxieux</li>\n                <li>Liés aux conditions de vie, <span class=\"kw-def\">isolement</span>, perte de repères affectifs et temporo-spatiaux</li>\n              </ul>\n            </td>\n            <td>Repérage clinique, EMPP</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 75 — Addiction <span class=\"kw-etio\">Tabac</span> · 76 — Addiction à l'<span class=\"kw-etio\">alcool</span> · 159 — <span class=\"kw-def\">Tuberculose</span> Enfant / Adulte · 162 — <span class=\"kw-clinique\">IST</span> · 152 — <span class=\"kw-def\">Endocardite</span> infectieuse</em></p>","frequence":1},{"id":"59-15","rang":"A","rubrique":"Prise en charge","titre":"Connaître le cumul des risques individuels chez les personnes précaires","contenu":"<div class=\"callout callout-info\">\n        <strong>Multifactorialité.</strong> La personne en situation de précarité ne présente <em>pas un risque isolé</em> mais un <strong>cumul de <span class=\"kw-def\">facteurs de risque</span></strong> qui s'additionnent et se potentialisent. La prévention doit donc être <strong>globale</strong>, pas focalisée sur un seul axe.\n      </div>\n\n      <h4>Catégories de risques cumulés</h4>\n\n      <table >\n        <thead>\n          <tr><th>Catégorie</th><th>Éléments</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Comportementaux</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-ttt\">Tabagisme</span></li>\n                <li><span class=\"kw-ttt\">Alcoolisation</span></li>\n                <li><span class=\"kw-etio\">Sédentarité</span></li>\n                <li>Alimentation déséquilibrée (malnutrition par défaut ou par excès)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Environnementaux</strong></td>\n            <td>\n              <ul>\n                <li>Logement insalubre, suroccupé, humide</li>\n                <li>Précarité énergétique → <span class=\"kw-alerte\">intoxications au CO</span> (appareils défectueux, mauvaise ventilation, période de grands froids)</li>\n                <li>Exposition professionnelle (pollution, accidents, pénibilité)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Sociaux</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-def\">Isolement</span> social, perte des liens familiaux</li>\n                <li>Ruptures (séparation, deuil, perte d'emploi)</li>\n                <li>Faible niveau d'éducation et littératie en santé</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Médicaux</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-def\">Comorbidités</span> multiples (<span class=\"kw-def\">HTA</span> + <span class=\"kw-def\">diabète</span> + addictions)</li>\n                <li>Discontinuité des soins, ruptures thérapeutiques</li>\n                <li>Retard diagnostique</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Spécifiques aux populations vulnérables</strong></td>\n            <td>\n              <ul>\n                <li><strong>Sans-abri</strong> : troubles respiratoires, parasitoses (<span class=\"kw-etio\">gale</span>, pédiculose), carences vitaminiques (B9, B12, B1), traumatismes, brûlures de <span class=\"kw-def\">contact</span>, surinfections</li>\n                <li><strong>Migrants</strong> : séquelles de violences, pathologies du pays d'origine, conditions de transport, mutilations sexuelles</li>\n                <li><strong>Femmes à la rue</strong> : agressions sexuelles, complications gynécologiques, <span class=\"kw-chiffre\">grossesse à rechercher</span> chez la femme en âge de procréer</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span class=\"kw-ci\">Grossesse</span> normale · 174 — Pathologie infectieuse du migrant</em></p>","frequence":0},{"id":"59-16","rang":"A","rubrique":"Prise en charge","titre":"Connaître le retard de prise en charge, le renoncement et les abandons des soins curatifs ou préventifs, la discontinuité des soins des personnes en situation de précarité","contenu":"<p>Quatre phénomènes intriqués qui aggravent l'état de santé des personnes précaires.</p>\n\n      <h4>1 · Retard de prise en charge</h4>\n\n      <ul>\n        <li>Délai allongé entre apparition des symptômes et 1<sup>re</sup> consultation</li>\n        <li>Conséquence directe : <strong>diagnostic à un <span class=\"kw-def\">stade</span> avancé</strong>, complications</li>\n        <li><strong><span class=\"kw-def\">Dépistage</span> organisé des cancers</strong> : <span class=\"kw-chiffre\">2× moindre</span> chez <span class=\"kw-clinique\">les</span> précaires → retard diagnostique cancérologique</li>\n        <li>Mauvaise hygiène bucco-dentaire → <span class=\"kw-alerte\">abcès bucco-dentaires</span> avec risque d'<strong><span class=\"kw-def\">endocardite</span> infectieuse</strong></li>\n      </ul>\n\n      <h4>2 · Renoncement aux soins</h4>\n\n      <div class=\"callout callout-info\">\n        <strong>Définition.</strong> Le <span class=\"kw-def\">renoncement aux soins</span> = ne pas consulter ni se faire soigner alors qu'on en a besoin. Pour <span class=\"kw-clinique\">les</span> personnes à faibles ressources, les questions de santé passent au <strong>second plan</strong> des priorités (logement, alimentation, travail).\n      </div>\n\n      <h4>Indicateurs d'inégalités d'accès aux soins</h4>\n\n      <table >\n        <thead>\n          <tr><th>Indicateur</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Accès géographique</strong></td>\n            <td>Distance, transports en commun, désert médical</td>\n          </tr>\n          <tr>\n            <td><strong>Montant des honoraires</strong></td>\n            <td>Secteur 1 <span class=\"kw-bio\">vs</span> secteur 2 (dépassements d'honoraires)</td>\n          </tr>\n          <tr>\n            <td><strong>Reste à charge (RAC)</strong></td>\n            <td>Avec ou sans mutuelle complémentaire</td>\n          </tr>\n          <tr>\n            <td><strong>Refus de soins</strong></td>\n            <td>\n              <ul>\n                <li><strong>Direct</strong> : impossibilité de rendez-vous</li>\n                <li><strong>Indirect</strong> : retard à la rédaction de documents réglementaires</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>3 · Abandon des soins curatifs ou préventifs</h4>\n\n      <ul>\n        <li>Arrêt d'un traitement chronique en cours (<span class=\"kw-def\">HTA</span>, <span class=\"kw-def\">diabète</span>, <span class=\"kw-ttt\">antirétroviraux</span>…)</li>\n        <li><strong>Couverture vaccinale</strong> : <span class=\"kw-chiffre\">2 à 4× moindre</span> chez <span class=\"kw-clinique\">les</span> précaires</li>\n        <li>Non-réalisation des dépistages organisés</li>\n      </ul>\n\n      <h4>4 · Discontinuité des soins</h4>\n\n      <ul>\n        <li>Absence de <strong>médecin traitant</strong> stable</li>\n        <li>Ruptures dans le <span class=\"kw-def\">suivi</span> des maladies chroniques</li>\n        <li>Perte d'information médicale entre <span class=\"kw-clinique\">les</span> structures</li>\n        <li>Conséquences : <span class=\"kw-alerte\">décompensations évitables</span>, hospitalisations en <span class=\"kw-alerte\">urgence</span>, surmortalité</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 152 — <span class=\"kw-def\">Endocardite</span> infectieuse · 290 — Epidémiologie cancers</em></p>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>Refus de soins <span class=\"kw-ci\">interdit</span> :</strong> refuser des soins au motif que le patient ne peut payer est <span class=\"kw-alerte\">contraire au Code de la santé publique dans tous les cas</span>.<br><strong>Sans droit ni statut :</strong> si une <span class=\"kw-alerte\">hospitalisation</span> est indiquée, elle se fait <span class=\"kw-ttt\">sous secret médical</span>.<br><strong>Grands froids (sans-abri) :</strong> rechercher une <span class=\"kw-alerte\">intoxication au CO</span> (chauffage défectueux) et des <span class=\"kw-etio\">troubles respiratoires</span>.<br><strong>Femme en âge de procréer à la rue :</strong> <span class=\"kw-ttt\">rechercher une grossesse</span> devant <span class=\"kw-clinique\">les</span> complications gynécologiques fréquentes.</p>","hospit":"<p><strong>PASS :</strong> <span class=\"kw-ttt\">permanence d'accès aux soins de santé</span> à l'hôpital, accès intégral et gratuit aux soins pour <span class=\"kw-clinique\">les</span> personnes <span class=\"kw-def\">démunies dépourvues d'assurance maladie</span> (y compris contraception, IVG, accueil de très jeunes enfants).<br><strong>LHSS :</strong> <span class=\"kw-ttt\">lits halte soins santé</span> pour le sans-abri dont l'état est <span class=\"kw-alerte\">incompatible avec la vie à la rue</span> mais ne nécessite pas d'<span class=\"kw-alerte\">hospitalisation</span> (<span class=\"kw-chiffre\">24h</span>/24, durée non limitée).<br><strong>EMPP :</strong> <span class=\"kw-ttt\">équipe mobile psychiatrie-précarité</span> qui va vers les personnes en grande précarité psychique <span class=\"kw-alerte\">empêchées d'accéder aux soins</span>.<br><strong><span class=\"kw-alerte\">SAMU</span> social :</strong> <span class=\"kw-alerte\">urgence</span> sociale, joignable au <span class=\"kw-chiffre\">115</span>.<br><strong>Services sociaux :</strong> <span class=\"kw-ttt\">obligatoirement sollicités</span> (CCAS, assistantes sociales CPAM/CARSAT, associations).</p>","redflags":"<ul><li><span class=\"kw-clinique\">Stigmates physiques</span> à l'examen : <span class=\"kw-clinique\">dénutrition</span>, <span class=\"kw-clinique\">lésions cutanées chroniques</span></li><li><span class=\"kw-clinique\">Troubles psychiques</span> : <span class=\"kw-clinique\">désorientation spatiotemporelle</span>, <span class=\"kw-etio\">dépression</span></li><li><span class=\"kw-alerte\">Intoxication au CO</span> en période de grands froids (chauffage défectueux, mauvaise ventilation)</li><li><span class=\"kw-etio\">Abcès bucco-dentaires</span> → risque d'<span class=\"kw-alerte\">endocardite</span></li><li><span class=\"kw-ttt\">Grossesse à rechercher</span> chez toute femme en âge de procréer vivant à la rue</li><li><span class=\"kw-etio\">Pathologies transmissibles</span> : <span class=\"kw-etio\">tuberculose</span>, <span class=\"kw-etio\">VIH</span>, <span class=\"kw-etio\">hépatites</span>, infections sexuelles</li><li><span class=\"kw-bio\">Carences vitaminiques</span> : <span class=\"kw-bio\">B9/B12</span> (personnes âgées), vitamines B (<span class=\"kw-etio\">alcool</span>)</li><li>Migrant : <span class=\"kw-alerte\">séquelles de violences</span>, <span class=\"kw-clinique\">déshydratation</span> du jeune enfant, <span class=\"kw-alerte\">mutilations sexuelles</span> chez <span class=\"kw-clinique\">les</span> filles</li></ul>","principes":"<p>Une <span class=\"kw-ttt\">prise en charge médicale sans démarche sociale est inutile</span> : la <span class=\"kw-def\">démarche pluriprofessionnelle</span> associe professionnels de santé et personnels sociaux pour ouvrir ou rouvrir <span class=\"kw-clinique\">les</span> droits.</p><p><strong>Démarche pluriprofessionnelle (santé + social)</strong></p><ul><li><span class=\"kw-ttt\">Services sociaux obligatoirement sollicités</span> pour l'ouverture des droits (revenu et frais de santé)</li><li>Objectif : limiter le <span class=\"kw-alerte\">cumul des risques</span> et la <span class=\"kw-alerte\">disqualification sociale</span></li></ul><p><strong>Couverture maladie</strong></p><p>Étranger irrégulier → AME ; résident stable et régulier → PUMa + CSS</p><ul><li><span class=\"kw-ttt\">PUMa</span> (remplace la CMU) = assurance maladie de base</li><li><span class=\"kw-ttt\">CSS</span> (remplace CMU-C + ACS) = complémentaire, ressources &lt; <span class=\"kw-chiffre\">~9 000–10 000 €/an</span> pour une personne isolée</li><li><span class=\"kw-ttt\">AME</span> = <span class=\"kw-def\">seule aide</span> ouvrable chez l'étranger en situation irrégulière (> <span class=\"kw-chiffre\">3 mois</span> de résidence, <span class=\"kw-ttt\">sans avance de frais</span>)</li></ul><p><strong>Aides financières</strong></p><ul><li><span class=\"kw-ttt\">RSA</span> : ≥ <span class=\"kw-chiffre\">25 ans</span>, RSA-socle ~<span class=\"kw-chiffre\">565 €/mois</span> (isolé), géré par <span class=\"kw-clinique\">les</span> conseils départementaux, contrepartie d'insertion ; <span class=\"kw-ci\">exclut l'étranger en situation irrégulière</span></li><li><span class=\"kw-ttt\">AAH</span> : ≥ <span class=\"kw-chiffre\">20 ans</span>, incapacité permanente ≥ <span class=\"kw-chiffre\">80 %</span></li><li><span class=\"kw-ttt\">ASPA/APA</span> : ≥ <span class=\"kw-chiffre\">60 ans</span>, Aggir <span class=\"kw-chiffre\">1 à 4</span> ; <span class=\"kw-ttt\">APL</span> ; <span class=\"kw-ttt\">AEEH</span> (parents d'un enfant <span class=\"kw-chiffre\">≤ 20 ans</span>)</li></ul><p><strong>Repérage de la précarité</strong></p><ul><li>Demander systématiquement : assurance maladie de base + complémentaire, difficultés à payer consultations/traitements</li><li><span class=\"kw-ttt\">Score EPICES</span> : <span class=\"kw-chiffre\">11 questions</span>, risque élevé si <span class=\"kw-chiffre\">≥ 4 réponses péjoratives</span> (= <span class=\"kw-def\">score</span> <span class=\"kw-chiffre\">30/100</span>), utilisé dans <span class=\"kw-clinique\">les</span> centres d'examens de santé</li></ul>","suivi":"<p><strong>Continuité des soins :</strong> lutter contre le <span class=\"kw-alerte\">renoncement, l'abandon et la discontinuité des soins</span> (curatifs et préventifs).<br><strong>Droits sociaux :</strong> ils peuvent être <span class=\"kw-alerte\">perdus s'ils ne sont pas renouvelés à temps</span>.<br><strong>Prévention à rattraper :</strong> <span class=\"kw-def\">dépistage</span> organisé des cancers <span class=\"kw-chiffre\">2× moindre</span>, couverture vaccinale <span class=\"kw-chiffre\">2 à 4× moindre</span>.<br><strong>Pathologies à suivre :</strong> <span class=\"kw-etio\">HTA</span>, <span class=\"kw-etio\">diabète</span>, <span class=\"kw-etio\">obésité</span>, conduites addictives (<span class=\"kw-etio\">alcool</span>, <span class=\"kw-etio\">tabac</span>).</p>"},"liensGlobaux":[{"href":"https://www.cetaf.fr/score-epices","label":"cetaf.fr"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Patient en situation de précarité repéré — Démarche pluriprofessionnelle santé + sociale ; jamais de soins refusés au motif du paiement","detail":"<h4>CAT — Couverture maladie & orientation du patient précaire — Quel dispositif selon le statut administratif et le besoin de soins</h4>","branches":[{"to":"q-urgence","label":"Patient précaire repéré","color":"blue"}]},{"id":"q-urgence","kind":"decision","label":"Soins aigus ou hospitalisation nécessaires d'emblée ?","branches":[{"to":"t-urgence","label":"Oui","color":"red"},{"to":"q-statut","label":"Non — ouverture des droits","color":"blue"}]},{"id":"t-urgence","kind":"terminal","label":"Soins urgents — jamais refusés — Primauté absolue sur la situation administrative","color":"red","detail":"<h4>Conduite</h4><ul><li>Refuser des soins au motif que le patient ne peut payer est <span class=\"kw-alerte\">contraire au Code de la santé publique dans tous les cas</span>.</li><li><span class=\"kw-alerte\">Hospitalisation</span> d'un patient sans droit ni statut : réalisée <span class=\"kw-ttt\">sous secret médical</span>.</li></ul><h4>Orientation</h4><ul><li>Personne démunie dépourvue d'assurance maladie → <span class=\"kw-ttt\">PASS</span> (accès intégral aux soins, délivrance gratuite).</li></ul>"},{"id":"q-statut","kind":"decision","label":"Étranger en situation irrégulière ? — Sans titre de séjour ni récépissé de demande","branches":[{"to":"q-residence","label":"Oui (étranger irrégulier)","color":"blue"},{"to":"t-puma-css","label":"Non (résident stable et régulier)","color":"green"}]},{"id":"q-residence","kind":"decision","label":"Résidence en France stable et ininterrompue <span class=\"kw-chiffre\">> 3 mois</span> ? — Et ressources < plafond CSS, sans couverture maladie","branches":[{"to":"t-ame","label":"Oui · ressources < plafond CSS","color":"blue"},{"to":"t-ame-humanitaire","label":"Non / simple passage en France","color":"blue"}]},{"id":"t-ame","kind":"terminal","label":"Étranger en situation irrégulière → AME — Résidence stable et ininterrompue > 3 mois","color":"blue","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">AME</span> = <span class=\"kw-def\">seule aide ouvrable chez l'étranger en situation irrégulière</span> (sans titre de séjour ni récépissé, sans couverture maladie, ressources < plafond CSS).</li><li>PEC à <span class=\"kw-chiffre\">100 %</span> des soins et de l'<span class=\"kw-alerte\">hospitalisation</span> (tarifs Sécurité sociale), <span class=\"kw-ttt\">SANS AVANCE DE FRAIS</span>.</li><li>Exonération de la franchise médicale, de la participation forfaitaire et du forfait journalier.</li><li>Enfants mineurs étrangers : AME accordée <span class=\"kw-chiffre\">sans conditions</span>.</li></ul>"},{"id":"t-ame-humanitaire","kind":"terminal","label":"Étranger ne résidant pas en France → AME humanitaire — À la demande d'un médecin","color":"blue","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">AME à titre humanitaire</span> : accident ou maladie lors du passage en France, soins impossibles dans le pays d'origine, <span class=\"kw-alerte\">urgence avec pronostic vital engagé</span>, femmes enceintes et nouveau-nés, <span class=\"kw-etio\">maladies contagieuses</span>.</li><li>Accordée ou refusée par le <span class=\"kw-ttt\">ministère chargé de l'Action sociale</span>.</li></ul>"},{"id":"t-puma-css","kind":"terminal","label":"Résident régulier → couverture de droit commun — Démarche sociale conjointe pour ouvrir les droits","color":"green","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">PUMa</span> (remplace la CMU) = assurance maladie de base.</li><li><span class=\"kw-ttt\">CSS</span> (remplace CMU-C + ACS) si ressources &lt; <span class=\"kw-chiffre\">~9 000 €/an</span> (jusqu'à <span class=\"kw-chiffre\">10 000 €/an</span> avec légère participation) pour une personne isolée.</li><li>CSS : <span class=\"kw-ttt\">sans avance de frais</span>, forfaits <span class=\"kw-ttt\">100 % Santé</span> (dentaire, optique, auditif), sans franchise médicale, exonération du forfait journalier.</li></ul>"}]},"cards":[{"i":"082844983f29","n":59,"o":"59-1","u":"Définition","t":"Connaître la définition de la précarité","q":"Comment la précarité se distingue-t-elle de la pauvreté ?","a":"<p>La précarité est une notion <strong>plus large</strong> que celle de la pauvreté. Un individu en situation de précarité n'est pas forcément pauvre ni exclu.</p>"},{"i":"1edbb0609414","n":59,"o":"59-1","u":"Définition","t":"Connaître la définition de la précarité","q":"Quelle est la définition de la précarité en santé publique ?","a":"<p>La précarité est l'<strong>absence d'une ou plusieurs des sécurités</strong> permettant aux personnes et aux familles d'assumer leurs obligations professionnelles, familiales et sociales et de jouir de leurs droits fondamentaux.</p>"},{"i":"74b4f8a11a27","n":59,"o":"59-1","u":"Définition","t":"Connaître la définition de la précarité","q":"Quelles sont les conditions indispensables à la santé identifiées par l'OMS et menacées par la précarité ?","a":"<ul><li>Se loger et se nourrir convenablement en quantité et qualité (attention, ce n'est pas « à volonté »).</li><li>Accéder à l'éducation et à l'information.</li><li>Disposer d'un revenu suffisant, certain et stable.</li><li>Bénéficier d'un écosystème stable et protecteur.</li><li>Compter sur un apport durable de ressources.</li><li>Avoir droit à la justice sociale et à un traitement équitable.</li><li>Sécurité physique et affective.</li><li>Capacités de communiquer, apprendre et s'exprimer.</li></ul>"},{"i":"1927cf36b78d","n":59,"o":"59-10","u":"Prise en charge","t":"Connaître les parcours de soins spécifiques des personnes en situation de précarité : PASS, LHSS, équipes mobiles psychiatrie-précarité (EMPP), structures associatives","q":"Quelle est la mission principale des Permanences d'Accès aux Soins de Santé (PASS) dans la prise en charge des personnes démunies ?","a":"<p>Les PASS ont pour mission principale de faciliter l'accès au système de soins hospitalier. Elles proposent des consultations externes, des actes diagnostiques et thérapeutiques <strong>gratuits</strong> pour les personnes démunies, dépourvues d'Assurance maladie. Elles assurent également un <strong>accompagnement aux démarches sociales</strong>, comme l'ouverture des droits.</p>"},{"i":"262c2efb5237","n":59,"o":"59-10","u":"Prise en charge","t":"Connaître les parcours de soins spécifiques des personnes en situation de précarité : PASS, LHSS, équipes mobiles psychiatrie-précarité (EMPP), structures associatives","q":"Quel est le rôle des Équipes Mobiles Psychiatrie-Précarité (EMPP) et leur composition ?","a":"<p>Les EMPP ont pour rôle de prendre en charge les personnes en <strong>grande précarité psychique et sociale</strong>, qui sont empêchées d'accéder aux soins. Elles offrent un complément psychiatrique aux PASS. Les équipes sont composées d'<strong>infirmiers, psychiatres, psychologues, et assistants sociaux</strong>. Elles interviennent à l'extérieur des établissements pour le repérage précoce, l'évaluation et l'orientation vers le dispositif de soins de droit commun.</p>"},{"i":"53f6962883dd","n":59,"o":"59-10","u":"Prise en charge","t":"Connaître les parcours de soins spécifiques des personnes en situation de précarité : PASS, LHSS, équipes mobiles psychiatrie-précarité (EMPP), structures associatives","q":"Quels sont les principaux services sociaux en ville qui constituent une porte d'entrée locale pour les personnes en situation de précarité ?","a":"<p>Les principaux services sont les <strong>Centres Communaux d'Action Sociale (CCAS)</strong>, qui représentent la porte d'entrée locale. On trouve également les assistantes sociales des CPAM et des CARSAT (pour les personnes âgées), les services sociaux du département (comme la PMI pour les femmes enceintes et jeunes enfants), et les travailleurs sociaux des associations.</p>"},{"i":"ed9e9a761037","n":59,"o":"59-10","u":"Prise en charge","t":"Connaître les parcours de soins spécifiques des personnes en situation de précarité : PASS, LHSS, équipes mobiles psychiatrie-précarité (EMPP), structures associatives","q":"Citez deux types d'associations humanitaires intervenant auprès des personnes en situation de précarité, et donnez-en des exemples.","a":"<ul><li>Les associations <strong>généralistes</strong> comme ATD Quart-Monde, la Croix-Rouge, le Secours catholique ou le Secours populaire.</li><li>Les associations <strong>thématiques</strong> comme les Restos du Cœur, les Banques alimentaires ou le Planning familial.</li><li>Les associations dédiées aux <strong>migrants</strong> comme la CIMADE, le COMEDE ou l'ISM.</li></ul>"},{"i":"f58be8e5b05e","n":59,"o":"59-10","u":"Prise en charge","t":"Connaître les parcours de soins spécifiques des personnes en situation de précarité : PASS, LHSS, équipes mobiles psychiatrie-précarité (EMPP), structures associatives","q":"Qui sont les principaux bénéficiaires des Lits Halte Soins Santé (LHSS) et quelle est leur mission ?","a":"<p>Les LHSS sont destinés aux personnes <strong>sans domicile fixe</strong> dont la pathologie ne nécessite pas une prise en charge hospitalière spécialisée mais est incompatible avec la vie à la rue. Leur mission est de fournir un <strong>lit infirmier</strong>, une évaluation médico-sociale, un soutien psychoéducatif, et une orientation vers un hébergement pérenne, avec une prise en charge <strong>24h/24, tous les jours</strong> et une durée non limitée.</p>"},{"i":"143595e8353d","n":59,"o":"59-11","u":"Prise en charge","t":"Connaître la couverture médicale des personnes en situation de précarité","q":"Qu'est-ce que la Complémentaire Santé Solidaire (CSS) et quels sont ses critères d'éligibilité et avantages pour le patient ?","a":"<p>La <strong>Complémentaire Santé Solidaire (CSS)</strong> est un dispositif qui remplace la CMU-C et l'ACS. Elle s'adresse aux personnes vivant en France de façon stable et régulière et respectant des <strong>conditions de ressources</strong> (environ 9 000 €/an pour une personne isolée pour la version gratuite, jusqu'à 10 000 €/an avec participation financière).<br>Ses avantages incluent :<ul><li>Prise en charge <strong>sans avance de frais</strong> de la part complémentaire (ville et hôpital).</li><li>Forfaits dentaire, lunettes, prothèses auditives (peut bénéficier du <strong>100 % Santé</strong>).</li><li>Absence de franchise médicale sur les médicaments, actes paramédicaux et transports sanitaires.</li><li>Dispense de la participation forfaitaire et du forfait journalier.</li></ul></p>"},{"i":"662e010fc23b","n":59,"o":"59-11","u":"Prise en charge","t":"Connaître la couverture médicale des personnes en situation de précarité","q":"Quelle est l'Aide Médicale de l'État (AME) et qui peut en bénéficier en France ?","a":"<p>L'<strong>Aide Médicale de l'État (AME)</strong> est le seul dispositif de couverture maladie applicable aux <strong>étrangers en situation irrégulière</strong>. Pour en bénéficier, la personne doit être un étranger (de nationalité étrangère), se trouver en situation irrégulière (sans titre ou récépissé de séjour), résider en France de manière stable et ininterrompue depuis plus de <strong>3 mois</strong>, ne pas avoir de couverture maladie, et avoir des ressources inférieures au plafond de la CSS (environ 9-10 k€/an).<br>L'AME est automatiquement accordée <strong>sans conditions pour les enfants mineurs</strong>.</p>"},{"i":"938543025b6a","n":59,"o":"59-11","u":"Prise en charge","t":"Connaître la couverture médicale des personnes en situation de précarité","q":"Quand l'AME à titre humanitaire peut-elle être accordée ?","a":"<p>L'AME à titre humanitaire peut être accordée pour des personnes étrangères <strong>ne résidant pas en France</strong>, à la demande d'un médecin, dans des situations très spécifiques : un accident ou une maladie lors d'un passage en France (visa touristique/court séjour), si les soins sont impossibles dans le pays d'origine, en cas de <strong>soins d'urgence</strong> (pronostic vital engagé), pour les femmes enceintes et les nouveau-nés, ou pour des maladies contagieuses. La décision est prise par le ministère chargé de l'Action sociale.</p>"},{"i":"a37455851fc5","n":59,"o":"59-11","u":"Prise en charge","t":"Connaître la couverture médicale des personnes en situation de précarité","q":"Quels soins sont couverts par l'Aide Médicale de l'État (AME) et quelle est la particularité de sa prise en charge ?","a":"<p>L'Aide Médicale de l'État (AME) prend en charge à <strong>100 % les soins médicaux et d'hospitalisation</strong>, dans la limite des tarifs de la Sécurité sociale. La particularité est une prise en charge <strong>sans avance de frais</strong>. De plus, les bénéficiaires sont <strong>exonérés de la franchise médicale, de la participation forfaitaire et du forfait journalier</strong>.</p>"},{"i":"e6e35c851ca8","n":59,"o":"59-11","u":"Prise en charge","t":"Connaître la couverture médicale des personnes en situation de précarité","q":"Quelle est la couverture maladie de base en France et qui en bénéficie ?","a":"<p>La couverture maladie de base en France est la <strong>Protection Universelle Maladie (PUMa)</strong>. Elle remplace l'ancienne CMU (Couverture Maladie Universelle) et couvre toute personne résidant en France de façon stable et régulière, prenant en charge la part de base des dépenses de santé.</p>"},{"i":"0914322c80d9","n":59,"o":"59-12","u":"Prise en charge","t":"Connaître les aides financières","q":"Quel est l'objectif des minima sociaux dans la prise en charge d'un sujet en situation de précarité ?","a":"<p>L'objectif des minima sociaux est de <strong>limiter le cumul des risques</strong> qui mènent à un état de grande pauvreté.</p>"},{"i":"9787b0df765a","n":59,"o":"59-12","u":"Prise en charge","t":"Connaître les aides financières","q":"Quelles sont les conditions clés pour bénéficier du RSA (Revenu de Solidarité Active) en France ?","a":"<ul><li>Avoir <strong>≥ 25 ans</strong>, ou être parent isolé.</li><li>Avoir <strong>18-24 ans</strong> et avoir travaillé <strong>≥ 2 des 3 dernières années</strong>.</li><li>Résider en France (les étrangers doivent avoir un titre de séjour valide).</li><li>Avoir des <strong>revenus inférieurs au plafond</strong> défini.</li><li>S'engager dans un <strong>parcours d'insertion sociale ou professionnelle</strong> (contrepartie).</li></ul>"},{"i":"99af4b027af5","n":59,"o":"59-12","u":"Prise en charge","t":"Connaître les aides financières","q":"Quelle aide financière est destinée aux demandeurs d'emploi en fin de droits au chômage et quelles sont ses conditions ?","a":"<p>L'aide financière destinée aux demandeurs d'emploi en fin de droits est l'<strong>Allocation Spécifique de Solidarité (ASS)</strong>. Elle est accessible aux demandeurs d'emploi qui ont <strong>épuisé leurs droits au chômage</strong>.</p>"},{"i":"c068f470412f","n":59,"o":"59-12","u":"Prise en charge","t":"Connaître les aides financières","q":"Quel est le rôle du médecin et du travailleur social concernant le maintien des droits aux minima sociaux ?","a":"<p>Le rôle du médecin et du travailleur social est de <strong>vérifier régulièrement l'ouverture et le maintien des droits</strong> aux minima sociaux, afin d'éviter leur perte due, par exemple, à un non-renouvellement à temps.</p>"},{"i":"d4984df8663f","n":59,"o":"59-12","u":"Prise en charge","t":"Connaître les aides financières","q":"Quelles sont les conditions principales pour l'attribution de l'AAH (Allocation aux Adultes Handicapés) ?","a":"<ul><li>Avoir <strong>≥ 20 ans</strong>.</li><li>Résider en France.</li><li>Présenter une <strong>Incapacité Permanente (IP) ≥ 80 %</strong>.</li><li>Avoir des <strong>ressources sous un plafond annuel</strong> défini.</li></ul>"},{"i":"1932a709e8c2","n":59,"o":"59-13","u":"Prise en charge","t":"Connaître l’existence et les moyens de recours aux consultations gratuites","q":"Quels sont les principaux obstacles au non-recours aux soins pour les personnes en situation de précarité, malgré l'existence de dispositifs gratuits ?","a":"Le non-recours aux soins est un obstacle majeur à l'accès aux dispositifs gratuits. Les principales raisons sont :\n<ul>\n<li>La <strong>méconnaissance</strong> des dispositifs existants</li>\n<li>La <strong>peur du jugement</strong></li>\n<li>La <strong>complexité administrative</strong></li>\n<li>La <strong>barrière linguistique</strong></li>\n</ul>"},{"i":"f026f647c014","n":59,"o":"59-13","u":"Prise en charge","t":"Connaître l’existence et les moyens de recours aux consultations gratuites","q":"Quel est le rôle des PASS (Permanences d'Accès aux Soins de Santé) hospitalières dans l'accès aux soins des personnes démunies ?","a":"Les PASS hospitalières sont spécifiquement destinées aux <strong>personnes démunies</strong> dépourvues d'Assurance Maladie. Elles offrent des <strong>consultations</strong>, des <strong>actes diagnostiques et thérapeutiques gratuits</strong>, facilitant ainsi l'accès à des soins essentiels pour cette population."},{"i":"fd651a0aa2ee","n":59,"o":"59-13","u":"Prise en charge","t":"Connaître l’existence et les moyens de recours aux consultations gratuites","q":"Quelles sont les principales structures publiques offrant des consultations gratuites en France pour les personnes en situation de précarité ou sans couverture sociale ?","a":"Les principales structures publiques offrant des consultations gratuites sont :\n<ul>\n<li>Les <strong>Centres d'examen de santé de l'Assurance maladie</strong></li>\n<li>Les <strong>CDAG / CEGID</strong> (Centres de dépistage anonymes et gratuits)</li>\n<li>Les <strong>Dispensaires municipaux et centres de santé</strong></li>\n<li>Les <strong>PASS hospitalières</strong> (Permanences d'Accès aux Soins de Santé)</li>\n<li>Les <strong>PMI</strong> (Protection maternelle et infantile)</li>\n<li>Les <strong>Plannings familiaux</strong></li>\n<li>Les structures de <strong>soins psychiatriques sectorisés</strong> (CMP, CATTP)</li>\n</ul>"},{"i":"093e03666ae0","n":59,"o":"59-14","u":"Diagnostic positif","t":"Connaître les 5 grands domaines de pathologies les plus fréquentes chez les personnes en situation de précarité","q":"Quelles sont les pathologies transmissibles à dépister prioritairement chez les personnes en situation de précarité ?","a":"<p>Les pathologies transmissibles à dépister prioritairement sont :</p><ul><li>La <strong>tuberculose</strong>.</li><li>Le <strong>VIH</strong>.</li><li>Les <strong>hépatites B et C</strong>.</li><li>Les <strong>IST</strong> (infections sexuellement transmissibles).</li></ul>"},{"i":"0ee335a0b00c","n":59,"o":"59-14","u":"Diagnostic positif","t":"Connaître les 5 grands domaines de pathologies les plus fréquentes chez les personnes en situation de précarité","q":"Quelles sont les pathologies métaboliques clés à surveiller chez les personnes en situation de précarité ?","a":"<p>Les pathologies métaboliques clés à surveiller sont :</p><ul><li>Le <strong>diabète de la maturité</strong>.</li><li>L'<strong>obésité</strong>.</li><li>Les <strong>dyslipidémies</strong>.</li></ul>"},{"i":"114aa5709448","n":59,"o":"59-14","u":"Diagnostic positif","t":"Connaître les 5 grands domaines de pathologies les plus fréquentes chez les personnes en situation de précarité","q":"Quelles sont les pathologies cardiovasculaires clés à surveiller chez les personnes en situation de précarité ?","a":"<p>Les pathologies cardiovasculaires clés à surveiller sont :</p><ul><li>L'<strong>HTA</strong> (hypertension artérielle).</li><li>Les <strong>coronaropathies</strong>.</li><li>L'<strong>AOMI</strong> (artériopathie oblitérante des membres inférieurs).</li></ul>"},{"i":"1fc8a6df466e","n":59,"o":"59-14","u":"Diagnostic positif","t":"Connaître les 5 grands domaines de pathologies les plus fréquentes chez les personnes en situation de précarité","q":"Quelles sont les manifestations des troubles psychiatriques fréquemment rencontrées chez les personnes en situation de précarité ?","a":"<p>On observe fréquemment :</p><ul><li>Une majoration des <strong>antécédents psychiatriques</strong>.</li><li>Des épisodes de <strong>dépression</strong>.</li><li>Des <strong>troubles anxieux</strong>.</li></ul><p>Ces manifestations sont souvent liées aux conditions de vie, à l'isolement et à la perte de repères.</p>"},{"i":"6df4301208ab","n":59,"o":"59-14","u":"Diagnostic positif","t":"Connaître les 5 grands domaines de pathologies les plus fréquentes chez les personnes en situation de précarité","q":"Quels sont les 5 grands domaines de pathologies les plus fréquentes chez les personnes en situation de précarité ?","a":"<p>Les 5 grands domaines de pathologies les plus fréquentes sont :</p><ul><li>Les pathologies <strong>cardiovasculaires</strong>.</li><li>Les pathologies <strong>métaboliques</strong>.</li><li>Les <strong>addictions</strong>.</li><li>Les pathologies <strong>transmissibles</strong>.</li><li>Les troubles <strong>psychiatriques</strong>.</li></ul>"},{"i":"7dd99a94ab36","n":59,"o":"59-14","u":"Diagnostic positif","t":"Connaître les 5 grands domaines de pathologies les plus fréquentes chez les personnes en situation de précarité","q":"Quelles sont les consommations abusives à rechercher spécifiquement dans les addictions chez les personnes en situation de précarité ?","a":"<p>Il convient de rechercher des consommations abusives d'<strong>alcool</strong>, de <strong>tabac</strong> et de <strong>substances psychoactives</strong>.</p>"},{"i":"4d227d810bd1","n":59,"o":"59-15","u":"Prise en charge","t":"Connaître le cumul des risques individuels chez les personnes précaires","q":"Quelles sont les complications de santé spécifiques aux femmes à la rue ?","a":"<ul><li><strong>Agressions sexuelles</strong></li><li>Complications gynécologiques</li><li>La grossesse doit être systématiquement recherchée chez la <strong>femme en âge de procréer</strong></li></ul>"},{"i":"5a5cfe62ab2b","n":59,"o":"59-15","u":"Prise en charge","t":"Connaître le cumul des risques individuels chez les personnes précaires","q":"Décrivez les risques sociaux fréquemment rencontrés par les personnes en situation de précarité.","a":"<ul><li><strong>Isolement social</strong>, perte des liens familiaux</li><li>Ruptures (séparation, deuil, perte d'emploi)</li><li><strong>Faible niveau d'éducation</strong> et de littératie en santé</li></ul>"},{"i":"96ae52383478","n":59,"o":"59-15","u":"Prise en charge","t":"Connaître le cumul des risques individuels chez les personnes précaires","q":"Quels risques spécifiques peuvent affecter les personnes sans-abri ?","a":"<ul><li>Troubles respiratoires</li><li>Parasitoses (<strong>gale, pédiculose</strong>)</li><li><strong>Carences vitaminiques</strong> (B9, B12, B1)</li><li>Traumatismes et brûlures de contact</li><li>Surinfections</li></ul>"},{"i":"9a6927f8af18","n":59,"o":"59-15","u":"Prise en charge","t":"Connaître le cumul des risques individuels chez les personnes précaires","q":"Quelles sont les problématiques de santé spécifiques aux migrants en situation de précarité ?","a":"<ul><li>Séquelles de <strong>violences</strong></li><li>Pathologies du pays d'origine</li><li>Conséquences des <strong>conditions de transport</strong></li><li>Mutilations sexuelles</li></ul>"},{"i":"ac0d5c291933","n":59,"o":"59-15","u":"Prise en charge","t":"Connaître le cumul des risques individuels chez les personnes précaires","q":"Quels sont les risques médicaux spécifiques aux personnes en situation de précarité ?","a":"<ul><li><strong>Comorbidités multiples</strong> (par exemple, HTA, diabète, addictions)</li><li><strong>Discontinuité des soins</strong> et ruptures thérapeutiques</li><li><strong>Retard diagnostique</strong></li></ul>"},{"i":"d130df7f6e12","n":59,"o":"59-15","u":"Prise en charge","t":"Connaître le cumul des risques individuels chez les personnes précaires","q":"Quels sont les facteurs de risque environnementaux pour les personnes en situation de précarité ?","a":"<ul><li>Logement <strong>insalubre, suroccupé, humide</strong></li><li><strong>Précarité énergétique</strong>, entraînant des intoxications au CO</li><li>Exposition professionnelle (pollution, accidents, pénibilité)</li></ul>"},{"i":"e40689a7905a","n":59,"o":"59-15","u":"Prise en charge","t":"Connaître le cumul des risques individuels chez les personnes précaires","q":"Quels sont les facteurs de risque comportementaux couramment observés chez les personnes en situation de précarité ?","a":"<ul><li><strong>Tabagisme</strong></li><li><strong>Alcoolisation</strong></li><li><strong>Sédentarité</strong></li><li><strong>Alimentation déséquilibrée</strong> (malnutrition par défaut ou par excès)</li></ul>"},{"i":"fe51ba9f526e","n":59,"o":"59-15","u":"Prise en charge","t":"Connaître le cumul des risques individuels chez les personnes précaires","q":"Comment les risques se manifestent-ils chez une personne en situation de précarité ?","a":"<p>La personne en situation de précarité présente un <strong>cumul de facteurs de risque</strong> qui s'additionnent et se potentialisent, et non un risque isolé. La prévention doit donc être globale.</p>"},{"i":"46b80b4f0eb6","n":59,"o":"59-16","u":"Prise en charge","t":"Connaître le retard de prise en charge, le renoncement et les abandons des soins curatifs ou préventifs, la discontinuité des soins des personnes en situation de précarité","q":"Qu'est-ce que le retard de prise en charge des personnes en situation de précarité ?","a":"<p>Il s'agit d'un <strong>délai allongé</strong> entre l'apparition des symptômes et la première consultation médicale. Ce retard conduit souvent à un diagnostic à un <strong>stade avancé</strong> de la pathologie et à des <strong>complications</strong>, comme le montre le dépistage organisé des cancers <strong>deux fois moindre</strong> chez les personnes précaires ou le risque accru d'<strong>endocardite infectieuse</strong> lié à la mauvaise hygiène bucco-dentaire.</p>"},{"i":"50c427d8ba9f","n":59,"o":"59-16","u":"Prise en charge","t":"Connaître le retard de prise en charge, le renoncement et les abandons des soins curatifs ou préventifs, la discontinuité des soins des personnes en situation de précarité","q":"Qu'est-ce que la discontinuité des soins chez les personnes en situation de précarité et quelles en sont les conséquences ?","a":"<p>La discontinuité des soins se caractérise par une <strong>absence de médecin traitant stable</strong>, des ruptures dans le suivi des maladies chroniques et une perte d'information médicale entre les structures de soins. Les conséquences sont graves : des <strong>décompensations évitables</strong>, des <strong>hospitalisations en urgence</strong> et une <strong>surmortalité</strong>.</p>"},{"i":"b3d8484b264b","n":59,"o":"59-16","u":"Prise en charge","t":"Connaître le retard de prise en charge, le renoncement et les abandons des soins curatifs ou préventifs, la discontinuité des soins des personnes en situation de précarité","q":"Qu'est-ce que l'abandon des soins curatifs ou préventifs chez les personnes en situation de précarité ?","a":"<p>L'abandon des soins correspond à l'<strong>arrêt d'un traitement chronique</strong> en cours (par exemple, HTA, diabète, antirétroviraux) ou à la <strong>non-réalisation de mesures préventives</strong>. On observe une couverture vaccinale <strong>2 à 4 fois moindre</strong> et une non-réalisation des dépistages organisés chez les personnes précaires.</p>"},{"i":"ecd33b814b6c","n":59,"o":"59-16","u":"Prise en charge","t":"Connaître le retard de prise en charge, le renoncement et les abandons des soins curatifs ou préventifs, la discontinuité des soins des personnes en situation de précarité","q":"Qu'est-ce que le renoncement aux soins chez les personnes en situation de précarité ?","a":"<p>Le renoncement aux soins désigne le fait de <strong>ne pas consulter ou se faire soigner</strong>, malgré un besoin avéré, car la santé est reléguée au second plan des priorités (derrière le logement, l'alimentation, le travail). Il est influencé par des inégalités d'accès aux soins, incluant :</p><ul><li>l'<strong>accès géographique</strong> (distance, transports, désert médical)</li><li>le <strong>montant des honoraires</strong> (secteur 1 vs 2, dépassements)</li><li>le <strong>reste à charge</strong> (avec ou sans mutuelle)</li><li>le <strong>refus de soins</strong> direct (pas de rendez-vous) ou indirect (retard de documents).</li></ul>"},{"i":"51255abd124b","n":59,"o":"59-2","u":"Diagnostic positif","t":"Savoir distinguer la précarité de la pauvreté, de la grande pauvreté et de l’exclusion, de la marginalisation, et de la vulnérabilité","q":"Comment définit-on la pauvreté et la grande pauvreté en France ?","a":"<p>La pauvreté est définie par un <strong>niveau de vie inférieur au seuil de pauvreté</strong>, fixé à <strong>60 % du niveau de vie médian</strong> en France (soit environ <strong>1 008 €/mois pour un célibataire</strong>). La grande pauvreté, ou misère, se caractérise par la <strong>cumulation de défaillances socio-économiques, de ruptures familiales et d'accidents de santé</strong>, menant à une disqualification sociale et une marginalité subie.</p>"},{"i":"c04cacb175f9","n":59,"o":"59-2","u":"Diagnostic positif","t":"Savoir distinguer la précarité de la pauvreté, de la grande pauvreté et de l’exclusion, de la marginalisation, et de la vulnérabilité","q":"Quelle est la définition de la précarité en santé publique, et quels en sont les marqueurs clés ?","a":"<p>La précarité est une situation de <strong>fragilité ou d'insécurité économique, sociale et familiale</strong>. Elle touche environ <strong>20 à 25 % de la population</strong> en France. Ses marqueurs clés incluent le chômage, un faible revenu, des conditions de travail à risque et la nationalité étrangère.</p>"},{"i":"e6119f919fe8","n":59,"o":"59-2","u":"Diagnostic positif","t":"Savoir distinguer la précarité de la pauvreté, de la grande pauvreté et de l’exclusion, de la marginalisation, et de la vulnérabilité","q":"Quelle est la distinction entre l'exclusion sociale, la marginalisation et la vulnérabilité dans le contexte de la précarité ?","a":"<p>L'<strong>exclusion sociale</strong> est l'impossibilité de bénéficier des mêmes droits sociaux que d'autres individus ; c'est une forme extrême de la précarité. La <strong>marginalisation</strong> est un concept proche, désignant une rupture des liens sociaux faisant suite à une exclusion ou à une auto-exclusion. La <strong>vulnérabilité</strong> est un état de fragilité matérielle ou morale conférant un risque accru de subir un tort ou une exclusion sociale ; c'est une transition entre intégration solide et désaffiliation.</p>"},{"i":"88985031ff16","n":59,"o":"59-3","u":"Définition","t":"Connaître les principales situations à risque de précarité et le caractère dynamique de ces situations","q":"Quelles sont les principales situations socio-économiques à risque de précarité ?","a":"<ul><li><strong>Chômage</strong> (durable, intermittent ou de longue durée).</li><li><strong>Faible niveau de ressources</strong> (revenu sous le seuil de pauvreté).</li><li><strong>Conditions de travail à risque</strong> (statuts et contrats précaires, temps partiel non choisi, contrats saisonniers).</li></ul>"},{"i":"df3e38758062","n":59,"o":"59-3","u":"Définition","t":"Connaître les principales situations à risque de précarité et le caractère dynamique de ces situations","q":"Quelle est la particularité du caractère dynamique des situations de précarité ?","a":"<p>La précarité n'est <strong>pas un état figé</strong>, mais un <strong>processus évolutif</strong> qui peut s'aggraver (vers la grande pauvreté et l'exclusion) ou régresser (avec un retour à l'emploi et l'ouverture de droits sociaux). La trajectoire est <strong>réversible dans les deux sens</strong>.</p>"},{"i":"e49301647f85","n":59,"o":"59-3","u":"Définition","t":"Connaître les principales situations à risque de précarité et le caractère dynamique de ces situations","q":"Quelles sont les principales situations personnelles et environnementales à risque de précarité ?","a":"<ul><li><strong>Nationalité étrangère</strong>, en particulier en situation irrégulière.</li><li>Modes d'<strong>habitat insalubre</strong>, suroccupé ou temporaire.</li><li>Effets de <strong>rupture</strong> (deuils, isolement affectif, intermittence du travail, séparation).</li></ul>"},{"i":"e98d6c401fa4","n":59,"o":"59-3","u":"Définition","t":"Connaître les principales situations à risque de précarité et le caractère dynamique de ces situations","q":"Quelles sont les trois phases de la trajectoire sociale dans le concept dynamique de précarité ?","a":"<ul><li><strong>Intégration</strong> : stabilité professionnelle + réseau social.</li><li><strong>Vulnérabilité</strong> : fragilité matérielle ou morale, risque d'exclusion (= zone de bascule).</li><li><strong>Désaffiliation</strong> : chômage, isolement, perte des liens sociaux. L'intervention médico-sociale précoce est majeure au stade de vulnérabilité pour éviter le glissement vers la désaffiliation.</li></ul>"},{"i":"1757a327af81","n":59,"o":"59-4","u":"Epidémiologie","t":"Connaître l’épidémiologie de la précarité","q":"Combien de personnes sont en situation de grande pauvreté en France ?","a":"<p>Environ <strong>2 millions de personnes</strong> sont en situation de grande pauvreté en France.</p>"},{"i":"5885d45aa780","n":59,"o":"59-4","u":"Epidémiologie","t":"Connaître l’épidémiologie de la précarité","q":"Quelle est la prévalence de la pauvreté en France et le nombre de personnes concernées selon les chiffres de 2019 ?","a":"<p>La prévalence de la pauvreté en France est de <strong>14 à 15 %</strong> de la population, ce qui représente environ <strong>9 millions de personnes</strong> en 2019.</p>"},{"i":"6f1e1096d93a","n":59,"o":"59-4","u":"Epidémiologie","t":"Connaître l’épidémiologie de la précarité","q":"Comment est défini le seuil de pauvreté en France et quel montant correspond-il pour un célibataire ?","a":"<p>Le seuil de pauvreté correspond à <strong>60 % du niveau de vie médian</strong>. Pour un célibataire, cela représentait <strong>1 008 € par mois</strong>.</p>"},{"i":"9bd477653a9e","n":59,"o":"59-4","u":"Epidémiologie","t":"Connaître l’épidémiologie de la précarité","q":"Quelle est la prévalence estimée de la précarité en France ?","a":"<p>La prévalence de la précarité en France se situe entre <strong>20 et 25 % de la population</strong>.</p>"},{"i":"fe970911deaf","n":59,"o":"59-4","u":"Epidémiologie","t":"Connaître l’épidémiologie de la précarité","q":"Quel est le montant du RSA-socle pour une personne isolée et se situe-t-il au-dessus ou en dessous du seuil de pauvreté ?","a":"<p>Le montant du RSA-socle pour une personne isolée est de <strong>565 € par mois</strong>. Il se situe <strong>en dessous du seuil de pauvreté</strong>.</p>"},{"i":"0859d3957919","n":59,"o":"59-5","u":"Prise en charge","t":"Connaître la démarche pluriprofessionnelle (santé et sociale) nécessaire pour les personnes en situation de précarité","q":"Quels sont les axes clés et les acteurs impliqués dans la démarche pluriprofessionnelle de prise en charge d'une personne en situation de précarité ?","a":"<ul><li><strong>Repérage</strong>: Identification des situations masquées (peur du jugement), utilisation du score <strong>EPICES</strong>, recherche de <strong>stigmates physiques</strong> et troubles psychiatriques. Acteurs: Médecin traitant, PMI, centres de santé.</li><li><strong>Ouverture des droits</strong>: Accès à la <strong>PUMa</strong>, la <strong>CSS</strong>, l'<strong>AME</strong> (si situation irrégulière), et aux minima sociaux (<strong>RSA, AAH, ASS, APL</strong>). Acteurs: Assistante sociale, CPAM, CARSAT, CCAS.</li><li><strong>Soins curatifs & préventifs</strong>: Parcours coordonné, <strong>dépistages organisés</strong> (cancers, IST, hépatites), <strong>vaccinations à jour</strong>. Acteurs: Médecin généraliste, spécialistes, centres de dépistage.</li><li><strong>Accès aux dispositifs spécifiques</strong>: Orientation vers les <strong>PASS, LHSS, EMPP</strong>, le <strong>SAMU social (115)</strong>, et les associations humanitaires (Croix-Rouge, Restos du cœur, ATD…). Acteurs: Hôpital public, associations, structures médico-sociales.</li></ul>"},{"i":"45f92793fa01","n":59,"o":"59-5","u":"Prise en charge","t":"Connaître la démarche pluriprofessionnelle (santé et sociale) nécessaire pour les personnes en situation de précarité","q":"Comment le repérage des situations de précarité doit-il être mené par les professionnels de santé ?","a":"<p>Le repérage doit inclure l'identification des situations masquées, souvent liées à la <strong>peur du jugement</strong>. Des outils comme le score <strong>EPICES</strong> peuvent être utilisés dans les centres d'examen de santé. L'examen clinique doit être ciblé, recherchant des <strong>stigmates physiques</strong> ainsi que des <strong>troubles psychiques</strong>.</p>"},{"i":"7ff4f9566b2a","n":59,"o":"59-5","u":"Prise en charge","t":"Connaître la démarche pluriprofessionnelle (santé et sociale) nécessaire pour les personnes en situation de précarité","q":"Quelle est la règle d'or concernant la prise en charge d'une personne en situation de précarité ?","a":"<p>La prise en charge médicale d'une personne en situation de précarité est <strong>inutile sans une démarche sociale associée</strong>. Elle doit être obligatoirement <strong>pluriprofessionnelle</strong>, combinant les aspects de santé et les aspects sociaux, pour permettre la (ré-)ouverture des droits du patient.</p>"},{"i":"bcba40eca86b","n":59,"o":"59-5","u":"Prise en charge","t":"Connaître la démarche pluriprofessionnelle (santé et sociale) nécessaire pour les personnes en situation de précarité","q":"Quels sont les principaux droits sociaux auxquels les personnes en situation de précarité doivent avoir accès ?","a":"<ul><li><strong>PUMa</strong> (Protection Universelle Maladie) pour l'assurance maladie de base.</li><li><strong>CSS</strong> (Complémentaire Santé Solidaire) pour une complémentaire santé.</li><li><strong>AME</strong> (Aide Médicale d'État) pour les personnes en situation irrégulière.</li><li>Minima sociaux comme le <strong>RSA</strong> (Revenu de Solidarité Active), l'<strong>AAH</strong> (Allocation aux Adultes Handicapés), l'<strong>ASS</strong> (Allocation de Solidarité Spécifique), et les <strong>APL</strong> (Aides Personnalisées au Logement).</li></ul>"},{"i":"ca64718c3b5c","n":59,"o":"59-5","u":"Prise en charge","t":"Connaître la démarche pluriprofessionnelle (santé et sociale) nécessaire pour les personnes en situation de précarité","q":"Dans quel cadre national s'inscrivent les dispositifs de prise en charge des personnes en situation de précarité en France ?","a":"<p>Les dispositifs s'inscrivent dans le <strong>Programme Régional pour l'Accès à la Prévention et aux Soins (PRAPS)</strong>. Plus précisément, les actions actuelles relèvent du <strong>PRAPS 2018-2022</strong>.</p>"},{"i":"1a8ea65bf314","n":59,"o":"59-6","u":"Prise en charge","t":"Connaître les modalités de repérage des personnes en situation de précarité","q":"Quelles sont les questions clés à poser lors de l'interrogatoire orienté pour identifier une situation de précarité ?","a":"<p>Les questions clés portent sur :<ul><li>Le statut de l'<strong>Assurance maladie de base</strong> et d'une <strong>complémentaire</strong>.</li><li>Les <strong>difficultés à payer</strong> les consultations ou les traitements.</li><li>Les <strong>conditions de logement</strong> (insalubre, suroccupé, temporaire, sans domicile fixe).</li><li>Le <strong>statut professionnel</strong> (contrat précaire, temps partiel non choisi, chômage).</li><li>L'<strong>isolement social</strong> et les ruptures récentes (deuil, séparation, perte d'emploi).</li></ul></p>"},{"i":"7608b02b2737","n":59,"o":"59-6","u":"Prise en charge","t":"Connaître les modalités de repérage des personnes en situation de précarité","q":"Qu'est-ce que le Score EPICES et comment est-il utilisé pour le repérage de la précarité ?","a":"<p>Le <strong>Score EPICES</strong> (Évaluation de la Précarité et des Inégalités de santé dans les Centres d'Examens de Santé) est un <strong>outil multidimensionnel de 11 questions</strong>. Il est utilisé dans les enquêtes en population générale pour évaluer la précarité. Un <strong>risque élevé de précarité</strong> est considéré à partir de <strong>4 réponses « péjoratives » ou plus sur 11</strong>, ce qui correspond à un score approximatif de 30/100.</p>"},{"i":"bcd39ca791cb","n":59,"o":"59-6","u":"Prise en charge","t":"Connaître les modalités de repérage des personnes en situation de précarité","q":"Quels signes physiques et psychiques doivent alerter le clinicien quant à une situation de précarité ?","a":"<p>Les signes d'appel à rechercher sont :<ul><li><strong>Stigmates physiques</strong> : Malnutrition (perte de poids, dénutrition), lésions cutanées chroniques (ulcères, gale, pédiculose), hygiène bucco-dentaire défaillante (foyers infectieux).</li><li><strong>Troubles psychiques</strong> : Désorientation spatio-temporelle, syndrome dépressif, isolement, repli sur soi, méfiance vis-à-vis du système de soins.</li></ul></p>"},{"i":"dc973a4963bc","n":59,"o":"59-6","u":"Prise en charge","t":"Connaître les modalités de repérage des personnes en situation de précarité","q":"Quels sont les trois principaux piliers du repérage d'une personne en situation de précarité en médecine ?","a":"<p>Le repérage repose sur :<ul><li>Un <strong>interrogatoire orienté</strong>.</li><li>Un <strong>examen clinique attentif</strong>.</li><li>L'utilisation d'un <strong>outil dédié</strong>, tel que le Score EPICES.</li></ul></p>"},{"i":"62b8c74a0340","n":59,"o":"59-7","u":"Prise en charge","t":"Connaître l’obligation de prise en charge des médecins et le secret professionnel vis-à-vis d’une personne en situation de précarité","q":"Quelle est l'obligation déontologique fondamentale du médecin concernant la prise en charge d'un patient en situation de précarité ?","a":"<p>L'obligation fondamentale est une interdiction absolue de refuser des soins à un patient sous prétexte qu'il ne peut pas les payer. Cette obligation est inscrite dans le <strong>Code de la santé publique</strong> et ne souffre d'<strong>aucune exception</strong>, y compris pour les bénéficiaires de la <strong>CSS</strong> (Complémentaire Santé Solidaire) ou de l'<strong>AME</strong> (Aide Médicale d'État).</p>"},{"i":"6d2e13dcdc67","n":59,"o":"59-7","u":"Prise en charge","t":"Connaître l’obligation de prise en charge des médecins et le secret professionnel vis-à-vis d’une personne en situation de précarité","q":"Comment un refus de soins à un patient en situation de précarité peut-il se manifester ?","a":"<ul><li><strong>Refus direct</strong> : impossibilité de prendre rendez-vous, refus explicite de consultation.</li><li><strong>Refus indirect</strong> : retards importants dans la rédaction de documents, délais d'attente anormalement prolongés, ou orientation systématique vers un autre praticien sans motif légitime.</li></ul>"},{"i":"b4f3d8211d58","n":59,"o":"59-7","u":"Prise en charge","t":"Connaître l’obligation de prise en charge des médecins et le secret professionnel vis-à-vis d’une personne en situation de précarité","q":"Quel est le rôle du secret médical lorsqu'une hospitalisation est indiquée pour un patient sans droits ou sans statut ?","a":"<p>En cas d'hospitalisation d'un patient sans droits ou sans statut (comme un étranger en situation irrégulière), cette prise en charge se fait <strong>sous secret médical</strong>. Le médecin ne doit <strong>jamais signaler le statut administratif</strong> de ces patients aux autorités. Le secret médical est primordial et protège ces patients, y compris les migrants en situation irrégulière, les mineurs isolés et les victimes de violences, primant sur toute considération administrative.</p>"},{"i":"bbba5531bbf1","n":59,"o":"59-7","u":"Prise en charge","t":"Connaître l’obligation de prise en charge des médecins et le secret professionnel vis-à-vis d’une personne en situation de précarité","q":"Quelles sont les obligations spécifiques des professionnels de santé vis-à-vis des bénéficiaires de la CSS et de l'AME ?","a":"<ul><li><strong>Recevoir</strong> ces patients.</li><li><strong>Respecter les tarifs</strong> reconnus par l'Assurance maladie.</li><li>Pratiquer le <strong>tiers payant</strong> (dispense d'avance de frais) pour ces assurés sociaux.</li><li>Appliquer le <strong>parcours de soins coordonné</strong> (avec un médecin traitant) pour les bénéficiaires de la CSS.</li></ul>"},{"i":"38af73d3c3c0","n":59,"o":"59-8","u":"Définition","t":"Connaître la définition des inégalités sociales en santé et les quatre mécanismes principaux qui y participent ; connaître le concept de gradient social de santé et son impact sur l’espérance de vie","q":"Quelle est la définition des inégalités sociales en santé (ISS) ?","a":"<p>Les inégalités sociales en santé (ISS) sont des différences d'état de santé <strong>systématiques</strong>, <strong>évitables</strong> et <strong>injustes</strong>, observées entre différents groupes sociaux et reflétant leur <strong>position sociale</strong> (catégorie socioprofessionnelle, revenu, niveau d'éducation, conditions de logement).</p>"},{"i":"84683b3f17f1","n":59,"o":"59-8","u":"Définition","t":"Connaître la définition des inégalités sociales en santé et les quatre mécanismes principaux qui y participent ; connaître le concept de gradient social de santé et son impact sur l’espérance de vie","q":"Qu'est-ce que le concept de gradient social de santé et pourquoi est-il important ?","a":"<p>Le <strong>gradient social de santé</strong> est un concept central qui signifie que l'état de santé se dégrade <strong>progressivement</strong> à mesure que l'on descend l'échelle sociale. Il s'agit d'un <strong>continuum</strong> qui concerne toute la société, et non pas seulement une opposition binaire entre 'pauvres vs riches'.</p>"},{"i":"e8926f24f6bd","n":59,"o":"59-8","u":"Définition","t":"Connaître la définition des inégalités sociales en santé et les quatre mécanismes principaux qui y participent ; connaître le concept de gradient social de santé et son impact sur l’espérance de vie","q":"Quels sont les quatre mécanismes principaux qui participent aux inégalités sociales en santé (ISS) ?","a":"<ul><li>Les <strong>postes de travail dangereux ou pénibles</strong> (exposition à la pollution, rythmes intenses, accidents du travail).</li><li>Les <strong>styles de vie contraints par les faibles ressources</strong> (malnutrition, pollutions, transports longs et pénibles).</li><li>Le <strong>cumul de facteurs de risque individuels</strong> (plus forte consommation de produits psychotoxiques comme le <strong>tabac</strong> et l'<strong>alcool</strong>, sédentarité).</li><li>L'<strong>accès aux soins et à la prévention retardé</strong>, jugé non prioritaire ou différé par manque de ressources matérielles ou cognitives.</li></ul>"},{"i":"f17c3694ba85","n":59,"o":"59-8","u":"Définition","t":"Connaître la définition des inégalités sociales en santé et les quatre mécanismes principaux qui y participent ; connaître le concept de gradient social de santé et son impact sur l’espérance de vie","q":"Quel est l'impact des inégalités sociales sur l'espérance de vie en France ?","a":"<p>Les inégalités sociales ont un impact significatif sur l'espérance de vie. On observe par exemple un différentiel d'environ <strong>7 ans</strong> d'espérance de vie entre les cadres et les inactifs, et de <strong>6 ans</strong> entre les cadres et les ouvriers. Ces inégalités se retrouvent également dans l'<strong>espérance de vie en bonne santé</strong> et la <strong>santé perçue</strong>.</p>"},{"i":"80e06f7e80f1","n":59,"o":"59-9","u":"Epidémiologie, prévalence","t":"Savoir que santé et précarité entretiennent des relations réciproques","q":"Comment une mauvaise santé peut-elle renforcer la précarité chez un individu ?","a":"<p>Une santé dégradée peut renforcer la précarité par :</p><ul><li>La <strong>perte d'emploi</strong> en cas de maladie chronique ou de handicap.</li><li>Le <strong>reste à charge non couvert</strong> et les frais médicaux induits.</li><li>La <strong>perte de revenus</strong> pendant un arrêt de travail.</li><li>L'<strong>isolement social</strong> lié au handicap ou à la maladie.</li></ul><p>Ces facteurs peuvent conduire à la <strong>bascule vers la grande pauvreté</strong> et à la <strong>désaffiliation</strong>.</p>"},{"i":"9b07e0b4c7ca","n":59,"o":"59-9","u":"Epidémiologie, prévalence","t":"Savoir que santé et précarité entretiennent des relations réciproques","q":"Comment la précarité influence-t-elle la santé, dans le cadre de la boucle de rétroaction santé-précarité ?","a":"<p>La précarité dégrade la santé par plusieurs mécanismes :</p><ul><li>Des <strong>conditions de vie défavorables</strong> (logement insalubre, alimentation déséquilibrée).</li><li>Une <strong>exposition professionnelle accrue</strong> à des risques.</li><li>Un <strong>stress chronique</strong> et un <strong>isolement social</strong>.</li><li>Le <strong>renoncement aux soins et à la prévention</strong>.</li></ul><p>Ceci entraîne une <strong>surmorbidité</strong> (cardiovasculaire, métabolique, psychiatrique, infectieuse) et une <strong>surmortalité</strong>.</p>"},{"i":"e9b23b684de0","n":59,"o":"59-9","u":"Epidémiologie, prévalence","t":"Savoir que santé et précarité entretiennent des relations réciproques","q":"Pourquoi une démarche pluriprofessionnelle est-elle essentielle pour briser le cycle de la précarité et de la mauvaise santé ?","a":"<p>La démarche pluriprofessionnelle (médico-sociale) est indispensable car santé et précarité entretiennent une <strong>boucle de rétroaction</strong>. Agir uniquement sur l'axe médical ou uniquement sur l'axe social ne suffit pas à briser ce cycle, car chaque aspect influence et est influencé par l'autre. Une approche globale est nécessaire pour obtenir un impact durable.</p>"}]};